-- ════════════════════════════════════════════════════════
-- 251 — Huitième recensement : les ajouts aux fiches existantes,
--       lots 05 à 07 (quatorze lignes de gamme, treize paragraphes)
-- ────────────────────────────────────────────────────────
-- D'OÙ ILS VIENNENT. Comme la 250 : des marques que l'atlas n'avait pas
-- et qui n'auront pas de fiche, parce qu'elles appartiennent à une maison
-- qui en a déjà une — une ligne de son catalogue (`gamme`), ou la marque
-- d'un tiers qu'elle roule (`mention`, une phrase de son histoire et le
-- nom dans `brands.mentions`, que lit la recherche). Chaque rattachement
-- a été éprouvé sur des pages avant d'être écrit.
--
-- ── CE QUI ENTRE ────────────────────────────────────────
--   Lignes de gamme   Aksum et The Wise Man Maduro (Foundation Cigar
--                     Company) ; Carlos & Maria (Freud Cigar Co.) ;
--                     Odyssey (General Cigar) ; GR Specials Red Label
--                     (Gran Habano) ; Havana Q et The American (J.C.
--                     Newman) ; Outcast (Miami Cigar & Co.) ; Tabacos
--                     Baez (My Father) ; Island Jim (Oscar Valladares) ;
--                     Bold by Nish Patel (Rocky Patel) ; Rough Rider,
--                     Cuban Aristocrat et La Instructora (Tabacalera
--                     Palma)
--   Mentions          The Wise Man Corojo (Foundation) ; Buffalo Trace
--                     (General Cigar) ; G.H. (Gran Habano) ; Bentley
--                     (Joya de Nicaragua) ; Centaur Cigars (Kelner
--                     Boutique Factory) ; Dominican Santiago Selection,
--                     Quisqueya et R.A. Villamil (Kristoff) ; La Aroma
--                     del Caribe (La Aroma de Cuba) ; Tatiana (La
--                     Aurora) ; Old Henry Cigars (My Father) ; Rustico
--                     et Rustico Habano (Oliva) ; Oz Family (Ozgener
--                     Family Cigars) ; Astoria de Nicaragua (Plasencia) ;
--                     Inca (Tabacalera del Oriente)
--
-- ── CE QUE LA RELECTURE A ÉCARTÉ ────────────────────────
-- Plus de cinq ans sans trace, ou arrêtée : Don Antonio (la dernière
-- édition date de 2018), Botucal (annonces de septembre 2021), APR et Les
-- Privatiers (rien de daté depuis octobre 2021 ; Plasencia n'est pas
-- nommée), XEN by Nish Patel (aucune page datée depuis octobre 2021).
-- Fabricant que la maison ne nomme pas : La Estrella (General Cigar ne
-- l'a lancée qu'avec « Country of Origin: Not Disclosed »), Maria Mancini
-- et 5 Vegas, dont Plasencia n'est nommée que dans une page de 2006 ou
-- dans un texte de boutique que contredit la page de la ligne Classic.
-- A. Flores est déjà dans la gamme de PDR Cigars sous « A. Flores 1975 ».
-- Cuban Aristocrat, d'abord rangée en mention, entre en gamme : Jochy
-- Blanco, propriétaire de la fabrique, a racheté IndianHead en 2015.
-- Odyssey, passée au portefeuille de Forged Cigar Company le 1er août
-- 2025, reste chez General Cigar, dont STG la roule à Estelí.
--
-- ── À CORRIGER DANS LES FICHES HÔTES ────────────────────
-- Foundation (El Güegüense, que la fiche dit roulé chez A.J. Fernandez,
-- est retiré depuis 2024 et la production passe à My Father) ; General
-- Cigar (Punch Upper Cut et Cohiba Blue, que Cigar Coop place chez Forged
-- Cigar Company depuis le 14 janvier 2026) ; Miami Cigar & Co. (La Aurora
-- reprendrait sa propre distribution, selon un article de juillet 2023) ;
-- Ozgener Family Cigars, Rocky Patel et Tabacalera Palma (usines, 1936 ou
-- 1925). Ces corrections de champs viendront avec celle de Vegas de
-- Santiago.
--
-- ── DIVERGENCES ÉCRITES ─────────────────────────────────
-- Aksum, rebaptisée en février 2024 selon Foundation ; Amorío, roulé à
-- la Tabacalera William Ventura (Cigar Coop, Cigar Dojo) ou à El Maestro
-- (online-cigars.com) ; Havana Q, cousine de Quorum à plus gros calibres
-- (Cigar Coop) ; Island Jim, du nom d'un détaillant selon la presse ou
-- d'un ami surnommé selon le tri ; Tabacos Baez, short filler selon
-- Cigarsdaily et remplissage mixte selon une critique de 2010 ; Inca,
-- Inka Secret Blend au Royaume-Uni ; Rustico, dont le propriétaire du nom
-- n'est dit par aucune page.
--
-- Rejouable : chaque ajout est gardé par un LOCATE (le paragraphe, le
-- fragment de source) ou par le nom de la ligne ; la gamme est relue en
-- base et réécrite en littéral dans chaque langue ; sceaux `machine`.
-- ════════════════════════════════════════════════════════

-- ── Foundation Cigar Company — paragraphe : Wise Man, gamme : Aksum, The Wise Man Maduro ──
UPDATE `brands` SET
  `history` = IF(LOCATE('En mars 2024, Foundation a annoncé que le nom El Güegüense s', `history`) > 0, `history`, CONCAT(`history`, '

', 'En mars 2024, Foundation a annoncé que le nom El Güegüense s''effaçait : The Wise Man Corojo prend la place du premier mélange, refait, et la production quitte Aganorsa Leaf pour My Father Cigars S.A., que dirige Pepín García. Le nom The Wise Man datait de juillet 2017 : il avait d''abord servi à la déclinaison Maduro. En octobre 2026, le site de la maison présente The Wise Man Corojo avec une cape corojo ''99 nicaraguayenne, en quatre formats, de la Corona à la Doble Corona.')),
  `history_en` = IF(LOCATE('In March 2024, Foundation announced that the name El Güegüen', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'In March 2024, Foundation announced that the name El Güegüense was fading away: The Wise Man Corojo takes the place of the first blend, remade, and production moves from Aganorsa Leaf to My Father Cigars S.A., which is run by Pepín García. The name The Wise Man dated from July 2017: it had initially been used for the Maduro variant. In October 2026, the company''s website presents The Wise Man Corojo with a Nicaraguan corojo ''99 wrapper, in four sizes, from the Corona to the Doble Corona.')),
  `history_es` = IF(LOCATE('En marzo de 2024, Foundation anunció que el nombre El Güegüe', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'En marzo de 2024, Foundation anunció que el nombre El Güegüense se desvanecía: The Wise Man Corojo ocupa el lugar de la primera mezcla, rehecha, y la producción deja Aganorsa Leaf por My Father Cigars S.A., que dirige Pepín García. El nombre The Wise Man databa de julio de 2017: había servido en un principio para la variante Maduro. En octubre de 2026, el sitio web de la casa presenta The Wise Man Corojo con una capa corojo ''99 nicaragüense, en cuatro formatos, de la Corona a la Doble Corona.')),
  `history_de` = IF(LOCATE('Im März 2024 gab Foundation bekannt, dass der Name El Güegüe', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Im März 2024 gab Foundation bekannt, dass der Name El Güegüense verschwindet: The Wise Man Corojo tritt, neu angefertigt, an die Stelle der ersten Mischung, und die Produktion wechselt von Aganorsa Leaf zu My Father Cigars S.A., die Pepín García leitet. Der Name The Wise Man stammte aus dem Juli 2017: Er hatte anfangs der Maduro-Variante gedient. Im Oktober 2026 präsentiert die Website des Hauses The Wise Man Corojo mit einem nicaraguanischen Deckblatt corojo ''99, in vier Formaten, von der Corona bis zur Doble Corona.')),
  `history_zh` = IF(LOCATE('2024年三月，Foundation宣布El Güegüense这一名称正在淡出：The Wise Man Corojo', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '2024年三月，Foundation宣布El Güegüense这一名称正在淡出：The Wise Man Corojo取代首款拼配，并经重新制作，生产也从Aganorsa Leaf转至My Father Cigars S.A.，该公司由Pepín García掌管。The Wise Man这一名称始于2017年七月：它起初用于Maduro版本。2026年十月，该公司网站展示The Wise Man Corojo，采用尼加拉瓜corojo ''99茄衣，共四种规格，从Corona到Doble Corona。')),
  `history_ar` = IF(LOCATE('في مارس 2024 أعلنت Foundation أن اسم El Güegüense يتوارى: تح', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'في مارس 2024 أعلنت Foundation أن اسم El Güegüense يتوارى: تحلّ The Wise Man Corojo محل أول توليفة، بعد إعادة صنعها، وينتقل الإنتاج من Aganorsa Leaf إلى My Father Cigars S.A.، التي يديرها Pepín García. وكان اسم The Wise Man يعود إلى يوليو 2017: فقد استُخدم في البداية للنسخة Maduro. وفي أكتوبر 2026 يعرض موقع الشركة The Wise Man Corojo بغلاف خارجي corojo ''99 نيكاراغوي، بأربعة مقاسات، من Corona إلى Doble Corona.')),
  `gamme` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"L''assemblage fondateur, nommé d''après une satire coloniale transmise oralement pendant des siècles. Bois, cuir, une pointe de sucre roux, et une évolution nette entre le premier et le dernier tiers.","vitolas":["Corona Gorda","Toro"],"wrapper":"Corojo 99 de Jalapa"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"La racine nord de la maison : cape du Connecticut sur tripe nicaraguayenne. Sombre, terreux, sans amertume — et volontairement placé dans une gamme de prix accessible.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — la ligne corsée, cape broadleaf, chez A.J. Fernández ; le recensement de cet atlas la prenait pour une maison.","vitolas":[],"wrapper":"Broadleaf du Connecticut"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — le château de Downton Abbey sur une bague, Connecticut d''Équateur.","vitolas":[],"wrapper":"Connecticut d''Équateur"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — un hommage au Mexique et à ses Olmèques, cape San Andrés, Claro et Maduro.","vitolas":[],"wrapper":"San Andrés (Mexique)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","wrapper":"Sumatra d''Équateur","vitolas":[],"story":"Ancienne Metapa, rebaptisée en février 2024 pour une question de marque déposée, d''après Foundation, dont le fondateur écrit que le mélange reste le même ; Claro et Maduro, d''après Cigar Coop. Sous-cape Connecticut Broadleaf, tripe d''Estelí et de Jalapa, force annoncée de moyenne à corsée, en Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 et Doble Corona 7 x 54, roulée chez A.J. Fernández d''après Cigar Coop en avril 2024."},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Présentée à l''IPCPR 2017 comme déclinaison Maduro d''El Güegüense, avec une cape San Andrés mexicaine ; refaite en 2024 chez My Father Cigars, avec la même cape sur une sous-cape d''Estelí et de Jalapa et une tripe d''Estelí, de Condega et de Jalapa. Force moyenne selon la maison, en Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 et Doble Corona 7 x 54, par vingt."}]',
  `gamme_en` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"The founding blend, named after a colonial satire passed down orally for centuries. Wood, leather, a hint of brown sugar, and a clear evolution between the first and the last third.","vitolas":["Corona Gorda","Toro"],"wrapper":"Jalapa Corojo 99"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"The northern root of the house: Connecticut wrapper over Nicaraguan filler. Dark, earthy, without bitterness — and deliberately kept in an affordable price range.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — the full-bodied line, broadleaf wrapper, at A.J. Fernández; this atlas''s census took it for a house.","vitolas":[],"wrapper":"Connecticut broadleaf"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — the castle of Downton Abbey on a band, Ecuadorian Connecticut.","vitolas":[],"wrapper":"Ecuadorian Connecticut"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — a tribute to Mexico and its Olmecs, San Andrés wrapper, Claro and Maduro.","vitolas":[],"wrapper":"San Andrés (Mexico)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","wrapper":"Ecuadorian Sumatra","vitolas":[],"story":"Formerly Metapa, renamed in February 2024 over a trademark issue, according to Foundation, whose founder writes that the blend remains the same; Claro and Maduro, according to Cigar Coop. Connecticut Broadleaf binder, Estelí and Jalapa filler, strength stated as medium to full, in Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 and Doble Corona 7 x 54, rolled at A.J. Fernández according to Cigar Coop in April 2024."},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Presented at IPCPR 2017 as the Maduro variant of El Güegüense, with a Mexican San Andrés wrapper; remade in 2024 at My Father Cigars, with the same wrapper over a binder from Estelí and Jalapa and a filler from Estelí, Condega and Jalapa. Strength medium according to the company, in Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 and Doble Corona 7 x 54, twenty to a box."}]',
  `gamme_es` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"La liga fundacional, con el nombre de una sátira colonial transmitida oralmente durante siglos. Madera, cuero, una pizca de azúcar moreno, y una evolución neta entre el primer y el último tercio.","vitolas":["Corona Gorda","Toro"],"wrapper":"Corojo 99 de Jalapa"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"La raíz norte de la casa: capa del Connecticut sobre tripa nicaragüense. Oscuro, terroso, sin amargor — y situado a propósito en una gama de precios accesible.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — la línea fuerte, capa broadleaf, en A.J. Fernández; el censo de este atlas la tomaba por una casa.","vitolas":[],"wrapper":"Broadleaf de Connecticut"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — el castillo de Downton Abbey en una anilla, Connecticut de Ecuador.","vitolas":[],"wrapper":"Connecticut de Ecuador"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — un homenaje a México y a sus olmecas, capa San Andrés, Claro y Maduro.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","wrapper":"Sumatra de Ecuador","vitolas":[],"story":"Antigua Metapa, rebautizada en febrero de 2024 por una cuestión de marca registrada, según Foundation, cuyo fundador escribe que la mezcla sigue siendo la misma; Claro y Maduro, según Cigar Coop. Capote Connecticut Broadleaf, tripa de Estelí y de Jalapa, fuerza anunciada de medium a fuerte, en Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 y Doble Corona 7 x 54, enrollada en A.J. Fernández según Cigar Coop en abril de 2024."},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (México)","vitolas":[],"story":"Presentada en el IPCPR 2017 como variante Maduro de El Güegüense, con una capa San Andrés mexicana; rehecha en 2024 en My Father Cigars, con la misma capa sobre un capote de Estelí y de Jalapa y una tripa de Estelí, de Condega y de Jalapa. Fuerza medium según la casa, en Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 y Doble Corona 7 x 54, veinte por caja."}]',
  `gamme_de` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"Der Gründungsblend, benannt nach einer kolonialen Satire, die über Jahrhunderte mündlich überliefert wurde. Holz, Leder, ein Anflug von braunem Zucker und eine klare Entwicklung zwischen erstem und letztem Drittel.","vitolas":["Corona Gorda","Toro"],"wrapper":"Corojo 99 aus Jalapa"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"Die nördliche Wurzel des Hauses: Connecticut-Deckblatt über nicaraguanischer Einlage. Dunkel, erdig, ohne Bitterkeit — und bewusst in einer erschwinglichen Preislage gehalten.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — die kräftige Linie, Broadleaf-Deckblatt, bei A.J. Fernández; die Zählung dieses Atlas hielt sie für ein Haus.","vitolas":[],"wrapper":"Connecticut-Broadleaf"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — das Schloss von Downton Abbey auf einer Bauchbinde, ecuadorianisches Connecticut.","vitolas":[],"wrapper":"Ecuadorianisches Connecticut"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — eine Hommage an Mexiko und seine Olmeken, San-Andrés-Deckblatt, Claro und Maduro.","vitolas":[],"wrapper":"San Andrés (Mexiko)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","wrapper":"Sumatra aus Ecuador","vitolas":[],"story":"Frühere Metapa, im Februar 2024 wegen einer Markenrechtsfrage umbenannt, laut Foundation, deren Gründer schreibt, dass die Mischung dieselbe bleibt; Claro und Maduro, laut Cigar Coop. Umblatt Connecticut Broadleaf, Einlage aus Estelí und Jalapa, angegebene Stärke von medium bis kräftig, in Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 und Doble Corona 7 x 54, laut Cigar Coop im April 2024 bei A.J. Fernández gerollt."},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Auf der IPCPR 2017 als Maduro-Variante von El Güegüense vorgestellt, mit einem mexikanischen Deckblatt San Andrés; 2024 bei My Father Cigars neu gefertigt, mit demselben Deckblatt über einem Umblatt aus Estelí und Jalapa und einer Einlage aus Estelí, Condega und Jalapa. Stärke medium laut Haus, in Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 und Doble Corona 7 x 54, zu je zwanzig in der Schachtel."}]',
  `gamme_zh` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"奠基配方，得名于一出口传数百年的殖民时期讽刺剧。木质、皮革，一丝红糖，从第一段到最后一段有清晰的推进。","vitolas":["Corona Gorda","Toro"],"wrapper":"哈拉帕可乐多99"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"这家的北方之根：康涅狄格茄衣配尼加拉瓜茄芯。深色、带土味、不苦——并有意保持在可及的价位。","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016年——浓烈的一线，broadleaf 茄衣，在 A.J. Fernández 制作；本图集的普查曾把它当作一家公司。","vitolas":[],"wrapper":"康涅狄格 broadleaf"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017年——茄标上的唐顿庄园城堡，厄瓜多尔康涅狄格茄衣。","vitolas":[],"wrapper":"厄瓜多尔康涅狄格"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"2022年 PCA——向墨西哥及其奥尔梅克人致敬，圣安德烈斯茄衣，Claro 与 Maduro。","vitolas":[],"wrapper":"圣安德烈斯（墨西哥）"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","wrapper":"厄瓜多尔Sumatra","vitolas":[],"story":"前身为Metapa，2024年二月因商标问题更名，据Foundation所述，其创始人写道，拼配保持不变；据Cigar Coop，为Claro和Maduro。茄套为Connecticut Broadleaf，茄芯来自Estelí和Jalapa，标称烟力为medium至浓郁，规格为Robusto 5 x 50、Corona Gorda 5½ x 48、Toro 6 x 52和Doble Corona 7 x 54，据Cigar Coop于2024年四月所述，在A.J. Fernández卷制。"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés（墨西哥）","vitolas":[],"story":"在IPCPR 2017上作为El Güegüense的Maduro版本亮相，采用墨西哥San Andrés茄衣；2024年在My Father Cigars重新制作，茄衣相同，茄套取自Estelí和Jalapa，茄芯取自Estelí、Condega和Jalapa。据该公司，烟力为medium，规格为Corona 5 x 48、Robusto 5½ x 50、Toro 6 x 52和Doble Corona 7 x 54，每盒二十支。"}]',
  `gamme_ar` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"الخلطة التأسيسية، المسمّاة على هجائية استعمارية تناقلتها الأفواه قروناً. خشب وجلد ولمسة سكر بنّي، مع تطوّر واضح بين الثلث الأول والأخير.","vitolas":["Corona Gorda","Toro"],"wrapper":"كوروخو 99 من خالابا"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"الجذر الشمالي للدار: غلاف كونيتيكت على حشوة نيكاراغوية. داكن، ترابي، بلا مرارة — وموضوع عمداً في نطاق سعري في المتناول.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — الخطّ القويّ، غلاف برودليف، لدى A.J. Fernández؛ وكان إحصاء هذا الأطلس يحسبه دارًا.","vitolas":[],"wrapper":"برودليف كونيتيكت"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — قصر داونتون آبي على حزام، كونيتيكت إكوادوري.","vitolas":[],"wrapper":"كونيتيكت إكوادوري"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — تحيّة للمكسيك وأولميكها، غلاف سان أندريس، Claro وMaduro.","vitolas":[],"wrapper":"سان أندريس (المكسيك)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","wrapper":"Sumatra من الإكوادور","vitolas":[],"story":"كان سابقًا Metapa، وأُعيدت تسميته في فبراير 2024 لمسألة تتعلق بالعلامة التجارية المسجّلة، بحسب Foundation التي يكتب مؤسسها أن التوليفة تبقى نفسها؛ Claro وMaduro، بحسب Cigar Coop. رابط Connecticut Broadleaf، وحشوة من Estelí وJalapa، وقوة معلنة بين medium وقوية، بمقاسات Robusto 5 x 50 وCorona Gorda 5½ x 48 وToro 6 x 52 وDoble Corona 7 x 54، يُلَفّ لدى A.J. Fernández بحسب Cigar Coop في أبريل 2024."},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","wrapper":"San Andrés (المكسيك)","vitolas":[],"story":"قُدّم في IPCPR 2017 بوصفه النسخة Maduro من El Güegüense، بغلاف خارجي San Andrés مكسيكي؛ وأُعيد صنعه في 2024 لدى My Father Cigars، بالغلاف نفسه فوق رابط من Estelí وJalapa وحشوة من Estelí وCondega وJalapa. قوة medium بحسب الشركة، بمقاسات Corona 5 x 48 وRobusto 5½ x 50 وToro 6 x 52 وDoble Corona 7 x 54، بواقع عشرين في العلبة."}]',
  `mentions` = '["Wise Man"]',
  `source` = IF(LOCATE('foundationcigarcompany.com « Aksum » (octobre 2026 : cape Su', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'foundationcigarcompany.com « Aksum » (octobre 2026 : cape Sumatra d''Équateur, sous-cape Connecticut Broadleaf, tripe d''Estelí et de Jalapa, force de moyenne à corsée, quatre formats) ; foundationcigarcompany.com « The Wise Man Corojo » et « The Wise Man Maduro » (octobre 2026 : cape corojo ''99 nicaraguayenne ou San Andrés mexicaine, sous-cape d''Estelí et de Jalapa, tripe d''Estelí, de Condega et de Jalapa, force moyenne, quatre formats, boîtes de vingt) ; cigar-coop.com « Foundation Cigar Company to Rebrand Metapa as Aksum | Cigar News » (20 février 2024 : Metapa renommée Aksum pour une question de marque déposée, mélange inchangé, Claro et Maduro, boîtes de dix) ; cigar-coop.com « PCA 2024: Foundation Cigars » (10 avril 2024 : Aksum toujours produite par A.J. Fernández ; nom El Güegüense retiré, deux mélanges nouveaux The Wise Man Corojo et Maduro chez My Father Cigars après le départ d''Aganorsa Leaf) ; blindmanspuff.com « Foundation Revamps Wise Man/El Güegüense, Moves Production to My Father – Cigar News » (12 mars 2024, annonce de Foundation : production chez My Father Cigars S.A., que dirige Pepín García ; mise en vente à la mi-avril 2024) ; thecigarauthority.com « IPCPR 2017: Foundation Cigar Company » (13 juillet 2017 : The Wise Man Maduro, cape San Andrés mexicaine, déclinaison Maduro d''El Güegüense, The Wise Man comme nom principal sur la bague)')),
  `updated_at` = NOW()
 WHERE `name` = 'Foundation Cigar Company';

-- ── Freud Cigar Co. — gamme : Carlos & Maria ──
UPDATE `brands` SET
  `gamme` = '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","story":"Le premier cigare, au printemps 2022 — le surmoi. Cinq mois avant l''incendie.","vitolas":[],"wrapper":"Non divulguée"},{"name":"AlterEgo","color":"#6B4226","force":"Medium","story":"Sorti en 2023, pendant la reconstruction de la fabrique.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Carlos & Maria","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"Marque sœur née chez Agape Lifestyle Inc., maison mère de Freud, et montrée au PCA 2023 sous le stand de Freud, sur le thème d''un couple : Amorío d''abord (août 2023), puis Orgasmo en juin 2024, édition limitée de 500 boîtes de dix. Amorío porte une cape de graine habano cultivée en Équateur sur une sous-cape Sumatra d''Indonésie, en Robusto 5 x 50, Corona Gorda 5½ x 46, Toro 6 x 54 et Churchill 7 x 48, mélange de Wiber Ventura, roulé à Tabacalera William Ventura d''après Cigar Coop, à El Maestro d''après un détaillant."}]',
  `gamme_en` = '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","story":"The first cigar, spring 2022 — the superego. Five months before the fire.","vitolas":[],"wrapper":"Undisclosed"},{"name":"AlterEgo","color":"#6B4226","force":"Medium","story":"Released in 2023, during the rebuilding of the factory.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Carlos & Maria","color":"#8B5A2B","force":"Medium-Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"Sister brand born at Agape Lifestyle Inc., Freud''s parent company, and shown at PCA 2023 on the Freud stand, on the theme of a couple: Amorío initially (August 2023), then Orgasmo in June 2024, a limited edition of 500 boxes of ten. Amorío has a wrapper of habano seed grown in Ecuador over a Sumatra binder from Indonesia, in Robusto 5 x 50, Corona Gorda 5½ x 46, Toro 6 x 54 and Churchill 7 x 48, a blend by Wiber Ventura, rolled at Tabacalera William Ventura according to Cigar Coop, at El Maestro according to a retailer."}]',
  `gamme_es` = '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","story":"El primer puro, primavera de 2022 — el superyó. Cinco meses antes del incendio.","vitolas":[],"wrapper":"No divulgada"},{"name":"AlterEgo","color":"#6B4226","force":"Medium","story":"Salido en 2023, durante la reconstrucción de la fábrica.","vitolas":[],"wrapper":"No divulgada"},{"name":"Carlos & Maria","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"Marca hermana nacida en Agape Lifestyle Inc., casa matriz de Freud, y mostrada en el PCA 2023 en el stand de Freud, con el tema de una pareja: en un comienzo Amorío (agosto de 2023), después Orgasmo en junio de 2024, edición limitada de 500 cajas de diez. Amorío lleva una capa de semilla habano cultivada en Ecuador sobre un capote Sumatra de Indonesia, en Robusto 5 x 50, Corona Gorda 5½ x 46, Toro 6 x 54 y Churchill 7 x 48, mezcla de Wiber Ventura, enrollada en Tabacalera William Ventura según Cigar Coop, en El Maestro según un minorista."}]',
  `gamme_de` = '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","story":"Die erste Zigarre, Frühjahr 2022 — das Über-Ich. Fünf Monate vor dem Feuer.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"AlterEgo","color":"#6B4226","force":"Medium","story":"Erschienen 2023, während des Wiederaufbaus der Fabrik.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Carlos & Maria","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano aus Ecuador","vitolas":[],"story":"Schwestermarke, entstanden bei Agape Lifestyle Inc., der Muttergesellschaft von Freud, und auf der PCA 2023 am Stand von Freud gezeigt, mit dem Thema eines Paares: zunächst Amorío (August 2023), dann Orgasmo im Juni 2024, limitierte Auflage von 500 Schachteln zu zehn. Amorío trägt ein Deckblatt aus in Ecuador angebauter Habano-Saat über einem Sumatra-Umblatt aus Indonesien, in Robusto 5 x 50, Corona Gorda 5½ x 46, Toro 6 x 54 und Churchill 7 x 48, eine Mischung von Wiber Ventura, laut Cigar Coop bei Tabacalera William Ventura gerollt, laut einem Einzelhändler bei El Maestro."}]',
  `gamme_zh` = '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","story":"2022年春的第一支——超我。火灾前五个月。","vitolas":[],"wrapper":"未公开"},{"name":"AlterEgo","color":"#6B4226","force":"Medium","story":"2023年、工厂重建期间推出。","vitolas":[],"wrapper":"未公开"},{"name":"Carlos & Maria","color":"#8B5A2B","force":"Medium-Full","wrapper":"厄瓜多尔Habano","vitolas":[],"story":"姐妹品牌，诞生于Freud的母公司Agape Lifestyle Inc.，于PCA 2023在Freud的展位上亮相，以一对伴侣为主题：先是Amorío（2023年八月），随后是2024年六月的Orgasmo，限量500盒，每盒十支。Amorío采用厄瓜多尔种植的habano种子茄衣，配印度尼西亚Sumatra茄套，规格为Robusto 5 x 50、Corona Gorda 5½ x 46、Toro 6 x 54和Churchill 7 x 48，拼配出自Wiber Ventura，据Cigar Coop，在Tabacalera William Ventura卷制，据一家零售商，则在El Maestro卷制。"}]',
  `gamme_ar` = '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","story":"السيجار الأوّل، ربيع 2022 — الأنا العليا. قبل الحريق بخمسة أشهر.","vitolas":[],"wrapper":"غير معلن"},{"name":"AlterEgo","color":"#6B4226","force":"Medium","story":"صدر سنة 2023، أثناء إعادة بناء المصنع.","vitolas":[],"wrapper":"غير معلن"},{"name":"Carlos & Maria","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano من الإكوادور","vitolas":[],"story":"علامة شقيقة وُلدت لدى Agape Lifestyle Inc.، الشركة الأم لـ Freud، وعُرضت في PCA 2023 في جناح Freud، حول موضوع زوجين: Amorío في البداية (أغسطس 2023)، ثم Orgasmo في يونيو 2024، إصدار محدود من 500 علبة، في كل علبة عشرة. يحمل Amorío غلافًا خارجيًا من بذور habano مزروعة في الإكوادور فوق رابط Sumatra من إندونيسيا، بمقاسات Robusto 5 x 50 وCorona Gorda 5½ x 46 وToro 6 x 54 وChurchill 7 x 48، توليفة من Wiber Ventura، تُلَفّ في Tabacalera William Ventura بحسب Cigar Coop، وفي El Maestro بحسب أحد تجار التجزئة."}]',
  `source` = IF(LOCATE('freudcigars.com (octobre 2026 : le site de la maison liste C', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'freudcigars.com (octobre 2026 : le site de la maison liste Carlos & Maria, avec les variantes Amorio et Orgasmo, parmi les lignes de Freud Cigar Co.) ; cigar-coop.com « Cigar News: Freud Cigar Company Launches Carlos & Maria Amorío » (2 août 2023 : marque sœur de Freud, mélange de Wiber Ventura, cape habano d''Équateur, sous-cape Sumatra d''Indonésie, quatre formats, roulé à Tabacalera William Ventura) ; cigar-coop.com « PCA 2023: Freud Cigar Co. » (19 août 2023 : marque lancée par Agape Lifestyle Inc., maison mère de Freud Cigar Company, montrée sous le stand de Freud) ; cigardojo.com « Freud Orgasmo Reaching Select Retailers » (11 juin 2024 : Orgasmo, deuxième cigare de la trilogie Carlos & Maria, 500 boîtes de dix, Tabacalera William Ventura) ; online-cigars.com « Freud Cigar Co. Carlos & Maria Corona Gorda » (octobre 2026 : force Medium-Full, Amorío roulé à El Maestro par Wiber Ventura, marque présentée comme sœur de Freud)')),
  `updated_at` = NOW()
 WHERE `name` = 'Freud Cigar Co.';

-- ── General Cigar — paragraphe : Buffalo Trace, gamme : Odyssey ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Buffalo Trace est le nom d''une distillerie du Kentucky, qui ', `history`) > 0, `history`, CONCAT(`history`, '

', 'Buffalo Trace est le nom d''une distillerie du Kentucky, qui s''est associée en juin 2021 à Cigars International pour une série de cigares vendue en gros par Meier & Dutch, la branche de distribution du détaillant. Roulée à General Cigar Dominicana, à Santiago, elle associe une cape Sumatra d''Équateur à une sous-cape arapiraca du Brésil. Une édition limitée, Special F, a suivi en septembre 2022, avec une sous-cape vieillie dans des fûts de la distillerie ; en octobre 2026, des détaillants proposent encore la série.')),
  `history_en` = IF(LOCATE('Buffalo Trace is the name of a Kentucky distillery, which pa', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Buffalo Trace is the name of a Kentucky distillery, which partnered in June 2021 with Cigars International for a cigar series sold wholesale by Meier & Dutch, the retailer''s distribution arm. Rolled at General Cigar Dominicana, in Santiago, it combines an Ecuadorian Sumatra wrapper with an arapiraca binder from Brazil. A limited edition, Special F, followed in September 2022, with a binder aged in barrels from the distillery; in October 2026, retailers still offer the series.')),
  `history_es` = IF(LOCATE('Buffalo Trace es el nombre de una destilería de Kentucky, qu', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Buffalo Trace es el nombre de una destilería de Kentucky, que se asoció en junio de 2021 con Cigars International para una serie de puros vendida al por mayor por Meier & Dutch, la rama de distribución del minorista. Enrollada en General Cigar Dominicana, en Santiago, combina una capa Sumatra de Ecuador con un capote arapiraca de Brasil. Una edición limitada, Special F, siguió en septiembre de 2022, con un capote envejecido en barricas de la destilería; en octubre de 2026, algunos minoristas todavía ofrecen la serie.')),
  `history_de` = IF(LOCATE('Buffalo Trace ist der Name einer Destillerie aus Kentucky, d', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Buffalo Trace ist der Name einer Destillerie aus Kentucky, die sich im Juni 2021 mit Cigars International für eine Zigarrenserie zusammengetan hat, die Meier & Dutch, der Vertriebszweig des Einzelhändlers, im Großhandel verkauft. Gerollt bei General Cigar Dominicana in Santiago, verbindet sie ein Sumatra-Deckblatt aus Ecuador mit einem arapiraca-Umblatt aus Brasilien. Eine limitierte Edition, Special F, folgte im September 2022, mit einem Umblatt, das in Fässern der Destillerie gereift ist; im Oktober 2026 bieten einige Einzelhändler die Serie weiterhin an.')),
  `history_zh` = IF(LOCATE('Buffalo Trace是肯塔基州一家蒸馏酒厂的名称，该厂于2021年六月与Cigars International合', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'Buffalo Trace是肯塔基州一家蒸馏酒厂的名称，该厂于2021年六月与Cigars International合作推出一个雪茄系列，由Meier & Dutch批发销售，后者是这家零售商的分销部门。该系列在Santiago的General Cigar Dominicana卷制，以厄瓜多尔Sumatra茄衣搭配巴西arapiraca茄套。2022年九月又推出限量版Special F，茄套在该酒厂的酒桶中陈放；2026年十月，仍有零售商销售该系列。')),
  `history_ar` = IF(LOCATE('Buffalo Trace هو اسم معمل تقطير في كنتاكي، تعاون في يونيو 20', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'Buffalo Trace هو اسم معمل تقطير في كنتاكي، تعاون في يونيو 2021 مع Cigars International في سلسلة سيجارات يبيعها بالجملة Meier & Dutch، فرع التوزيع التابع لتاجر التجزئة. تُلَفّ في General Cigar Dominicana في Santiago، وتجمع بين غلاف خارجي Sumatra من الإكوادور ورابط arapiraca من البرازيل. وتلتها في سبتمبر 2022 إصدار محدود هو Special F، برابط معتّق في براميل من معمل التقطير؛ وفي أكتوبر 2026 ما زال بعض تجار التجزئة يعرضون السلسلة.')),
  `gamme` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"La gamme la plus vendue de la maison aux États-Unis. Cape Connecticut Shade, douce et crémeuse, sur assemblage dominicain et jamaïcain. Notes de crème, cèdre léger, noisette. Format Café Baron de Rothschild (42 x 127mm). Le cigare des terrasses ensoleillées et des après-midi sans urgence.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Série inspirée des moteurs Harley-Davidson V-twin, aux formats nommés d''après des pièces : V660 Carb, V554 Piston, V770 Engine. Cape d''Équateur sur nicaraguayen et hondurien. Corsée, notes de cuir, café noir, chocolat. Cigare de route et d''Amérique profonde.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Équateur"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"La gamme haute de General Cigar sous le nom Punch. Cape maduro du Honduras sur nicaraguayen et hondurien. Notes de chocolat noir, bois fumé, poivre. La face obscure de Punch — puissante là où la gamme classique est accessible.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Maduro du Honduras"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"Le portefeuille de la famille Toraño, racheté en septembre 2014 — les marques seulement ; la société Toraño Family Cigar a cessé, et Charlie Toraño est resté consultant. Carlos Toraño est mort en février 2022. L''atlas avait supprimé un « Carlos Toraño Panama » inventé (204) ; la marque Toraño, elle, est réelle et vit ici.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Odyssey","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Marque de bundles à petit prix présentée par General Cigar à l''IPCPR 2016, d''origine Nicaragua, avec un Habano (cape habano nicaraguayenne) et un Connecticut (cape Connecticut Shade du Honduras) ; six déclinaisons en 2025, dont Full (septembre 2021), roulée à la main à STG Estelí. Depuis le 1er août 2025, STG la confie à l''équipe de vente de Forged Cigar Company, sans changement de produit."}]',
  `gamme_en` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"America''s best-seller for 30 years. Connecticut Shade wrapper, soft and creamy, over Dominican-Jamaican blend. Notes of cream, light cedar, hazelnut. The cigar of sunny terraces and unhurried afternoons. Consistent, accessible, never disappointing.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Series inspired by Harley-Davidson V-twin engines. Format names: V660 Carb, V554 Piston, V770 Engine. Ecuadorian wrapper over Nicaraguan-Honduran. Full body, notes of motorcycle leather, black coffee, chocolate, engine oil (really). A cigar of the open road, freedom, deep America.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuadorian"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"The premium General Cigar range under the Punch label. Honduran maduro wrapper over Nicaraguan-Honduran. Notes of dark chocolate, smoky wood, pepper. The dark side of Punch — powerful where the classic range is accessible.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Honduran Maduro"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"The Toraño family''s portfolio, bought in September 2014 — the brands only; the Toraño Family Cigar company ceased, and Charlie Toraño stayed on as a consultant. Carlos Toraño died in February 2022. This atlas had deleted an invented \\"Carlos Toraño Panama\\" (204); the Toraño brand itself is real and lives here.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Odyssey","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Brand of low-priced bundles presented by General Cigar at IPCPR 2016, of Nicaraguan origin, with a Habano (Nicaraguan habano wrapper) and a Connecticut (Honduran Connecticut Shade wrapper); six variants in 2025, including Full (September 2021), hand-rolled at STG Estelí. Since 1 August 2025, STG has entrusted it to the sales team of Forged Cigar Company, with no change to the product."}]',
  `gamme_es` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"El superventas estadounidense desde hace treinta años. Capa Connecticut Shade suave y cremosa sobre liga dominicano-jamaicana. Crema, cedro ligero, avellana. Formato Café Baron de Rothschild (42 x 127mm). El puro de las terrazas soleadas y de las tardes sin prisa. Regular, accesible, nunca decepciona.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Serie inspirada en los motores V-twin de Harley-Davidson, con formatos bautizados como piezas: V660 Carb, V554 Piston, V770 Engine. Capa de Ecuador sobre tripa nicaragüense y hondureña. Potente, con notas de cuero, café negro y chocolate. Un puro de carretera y de la América profunda.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuador"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"La gama premium de General Cigar bajo la etiqueta Punch. Capa hondureña maduro sobre nicaragüense-hondureño. Chocolate negro, madera ahumada, pimienta. La cara oscura de Punch: potente allí donde la gama clásica es accesible.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Maduro de Honduras"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"El portafolio de la familia Toraño, comprado en septiembre de 2014 — solo las marcas; la sociedad Toraño Family Cigar cesó, y Charlie Toraño quedó como consultor. Carlos Toraño murió en febrero de 2022. Este atlas había suprimido un «Carlos Toraño Panamá» inventado (204); la marca Toraño, en cambio, es real y vive aquí.","vitolas":[],"wrapper":"No divulgada"},{"name":"Odyssey","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Marca de bundles de precio bajo presentada por General Cigar en el IPCPR 2016, de origen Nicaragua, con un Habano (capa habano nicaragüense) y un Connecticut (capa Connecticut Shade de Honduras); seis variantes en 2025, entre ellas Full (septiembre de 2021), enrollada a mano en STG Estelí. Desde el 1 de agosto de 2025, STG la confía al equipo de ventas de Forged Cigar Company, sin cambio de producto."}]',
  `gamme_de` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"Der amerikanische Bestseller seit dreißig Jahren. Mildes, cremiges Connecticut-Shade-Deckblatt über dominikanisch-jamaikanischer Mischung. Sahne, leichte Zeder, Haselnuss. Format Café Baron de Rothschild (42 x 127 mm). Die Zigarre für sonnige Terrassen und Nachmittage ohne Eile. Gleichmäßig, zugänglich, nie enttäuschend.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Eine Serie, inspiriert von den V-Twin-Motoren von Harley-Davidson, mit Formaten, die wie Bauteile heißen: V660 Carb, V554 Piston, V770 Engine. Deckblatt aus Ecuador über nicaraguanischer und honduranischer Einlage. Kräftig, mit Noten von Leder, schwarzem Kaffee und Schokolade. Eine Zigarre der Landstraße und des tiefen Amerika.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuador"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"Die Premiumserie von General Cigar unter dem Label Punch. Honduranisches Maduro-Deckblatt über Nicaraguanisch-Honduranischem. Zartbitterschokolade, Rauchholz, Pfeffer. Die dunkle Seite von Punch — kraftvoll dort, wo die klassische Serie zugänglich ist.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Maduro aus Honduras"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"Das Portfolio der Familie Toraño, im September 2014 gekauft — nur die Marken; die Gesellschaft Toraño Family Cigar hörte auf, und Charlie Toraño blieb Berater. Carlos Toraño starb im Februar 2022. Dieser Atlas hatte ein erfundenes „Carlos Toraño Panama“ gelöscht (204); die Marke Toraño selbst ist real und lebt hier.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Odyssey","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Marke von bundles zu niedrigem Preis, von General Cigar auf der IPCPR 2016 vorgestellt, Herkunft Nicaragua, mit einem Habano (nicaraguanisches Habano-Deckblatt) und einem Connecticut (Deckblatt Connecticut Shade aus Honduras); sechs Varianten im Jahr 2025, darunter Full (September 2021), von Hand gerollt bei STG Estelí. Seit dem 1. August 2025 vertraut STG sie dem Vertriebsteam von Forged Cigar Company an, ohne Änderung am Produkt."}]',
  `gamme_zh` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"三十年来的美国畅销之作。柔和奶油般的康涅狄格阴植茄衣，内裹多米尼加与牙买加配方。奶油、轻盈雪松、榛子。Café Baron de Rothschild 规格（42 x 127 毫米）。这是阳光露台与不赶时间的午后的雪茄。稳定、平易，从不让人失望。","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"这一系列取材于哈雷戴维森的 V-twin 发动机，各规格以零件命名：V660 Carb、V554 Piston、V770 Engine。厄瓜多尔茄衣，包裹尼加拉瓜与洪都拉斯茄芯。风格厚重，带皮革、黑咖啡与巧克力的气息——属于公路与美国腹地的一支雪茄。","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"厄瓜多尔"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"General Cigar 以 Punch 之名推出的高端系列。洪都拉斯马杜罗茄衣，内裹尼加拉瓜与洪都拉斯烟叶。黑巧克力、烟熏木、胡椒。这是 Punch 阴暗的一面——在经典系列平易之处，它选择强劲。","vitolas":["Robusto","Toro","Churchill"],"wrapper":"洪都拉斯 Maduro"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"托拉尼奥家族的品牌组合，2014年9月买下——只有品牌；Toraño Family Cigar 公司停业，查理·托拉尼奥留任顾问。卡洛斯·托拉尼奥2022年2月去世。本图集曾删除一个杜撰的「Carlos Toraño Panama」（204）；Toraño 品牌本身是真实的，在这里延续。","vitolas":[],"wrapper":"未公开"},{"name":"Odyssey","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"低价位bundles品牌，由General Cigar在IPCPR 2016上亮相，原产国为尼加拉瓜，包含Habano版（尼加拉瓜habano茄衣）与Connecticut版（洪都拉斯Connecticut Shade茄衣）；2025年共有六个版本，其中包括Full（2021年九月），在STG Estelí手工卷制。自2025年八月1日起，STG将其交由Forged Cigar Company的销售团队负责，产品不变。"}]',
  `gamme_ar` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"الأكثر مبيعًا في أمريكا منذ ثلاثين عامًا. غلاف كونيتيكت شيد لطيف وقشديّ فوق خلطة دومينيكية-جامايكية. قشدة، أرز خفيف، بندق. قياس كافيه بارون دي روتشيلد (42 × 127 مم). سيجار الشرفات المشمسة والأصائل بلا عجلة. منتظم، سهل المنال، لا يخيّب.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"سلسلة مستوحاة من محرّكات هارلي ديفيدسون ثنائية الأسطوانة، بقياسات تحمل أسماء قطع المحرّك: V660 Carb وV554 Piston وV770 Engine. غلافة من الإكوادور فوق حشوة نيكاراغوية وهندوراسية. قوية، بنكهات الجلد والقهوة السوداء والشوكولاتة — سيجارة الطريق وأمريكا العميقة.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"إكوادوري"},{"name":"Punch Upper Cut","color":"#722F37","force":"Full","story":"المجموعة الراقية لجنرال سيغار تحت اسم بانش. غلاف هندوراسي مادورو فوق تبغ نيكاراغوي-هندوراسي. شوكولاتة داكنة، خشب مدخَّن، فلفل. إنه الوجه الداكن لبانش — قويّ حيث تكون المجموعة الكلاسيكية سهلة.","vitolas":["Robusto","Toro","Churchill"],"wrapper":"Maduro من هندوراس"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"محفظة عائلة تورانيو، اشتُريت في أيلول/سبتمبر 2014 — العلامات فقط؛ توقّفت شركة Toraño Family Cigar، وبقي تشارلي تورانيو مستشارًا. وتوفّي كارلوس تورانيو في شباط/فبراير 2022. كان هذا الأطلس قد حذف «Carlos Toraño Panama» مختلَقًا (204)؛ أمّا علامة Toraño فحقيقية وتعيش هنا.","vitolas":[],"wrapper":"غير معلن"},{"name":"Odyssey","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"علامة bundles منخفضة السعر قدّمتها General Cigar في IPCPR 2016، بلد المنشأ نيكاراغوا، تضم Habano (غلاف خارجي habano نيكاراغوي) وConnecticut (غلاف خارجي Connecticut Shade من هندوراس)؛ ست نسخ في 2025، منها Full (سبتمبر 2021)، تُلَفّ يدويًا في STG Estelí. ومنذ 1 أغسطس 2025 تُسندها STG إلى فريق المبيعات في Forged Cigar Company، دون تغيير في المنتج."}]',
  `mentions` = '["Buffalo Trace"]',
  `source` = IF(LOCATE('thedailypour.com « One of America''s Favorite Whiskey Distill', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'thedailypour.com « One of America''s Favorite Whiskey Distilleries Now Has Its Own Cigar Line » (22 juin 2021 : série Buffalo Trace lancée avec Cigars International, produite par General Cigar Dominicana à Santiago) ; manofmany.com « Buffalo Trace Now Has Its Own Cigar Line » (21 juin 2021 : cape Sumatra d''Équateur, sous-cape arapiraca du Brésil, tripe dominicaine et nicaraguayenne, roulée à General Cigar Dominicana) ; cigar-coop.com « Cigar News: Meier & Dutch to Release Buffalo Trace Special F » (26 septembre 2022 : Special F, sous-cape vieillie six mois en fûts de Buffalo Trace, roulée à General Cigar Dominicana, vendue par Meier & Dutch, branche de distribution de Cigars International) ; cigarsdirect.com « Buffalo Trace » (octobre 2026 : lignes Special S, Special L, Special F et Limited Edition 2025 au catalogue, faites par General Cigar à Santiago) ; cigar-coop.com « Cigar News: General Cigar Unveils Odyssey at 2016 IPCPR » (10 septembre 2016 : Odyssey présentée par General Cigar Company, bundles, Habano et Connecticut, pays d''origine Nicaragua) ; blindmanspuff.com « General Cigar Adds Odyssey Full to Odyssey Line – Cigar News » (10 septembre 2021 : Odyssey Full roulée à la main à STG Estelí) ; cigar-coop.com « STG Moves Odyssey Brand from General Cigar to Forged Cigar Portfolio » (14 juillet 2025 : Odyssey, marque de bundles lancée en 2016, passe chez Forged au 1er août 2025 ; six déclinaisons : Connecticut, Habano, Maduro, Sweet Tip, Coffee, Full)')),
  `updated_at` = NOW()
 WHERE `name` = 'General Cigar';

-- ── Gran Habano — paragraphe : G.H., gamme : GR Specials Red Label ──
UPDATE `brands` SET
  `history` = IF(LOCATE('En octobre 2026, la page du détaillant allemand Cigarworld p', `history`) > 0, `history`, CONCAT(`history`, '

', 'En octobre 2026, la page du détaillant allemand Cigarworld présente sous le nom G.H. des cigares de Guillermo Rico, roulés à Danlí, au Honduras, vendus en Europe : le droit européen y interdit, écrit-il, de faire valoir une indication géographique pour un produit qui n''en vient pas, et le nom d''origine évoque La Havane. Les lignes de G.H., Connecticut No. 1, Criollo No. 3 et Corojo No. 5, reprennent les trois chiffres de Gran Habano, où le No. 3 s''appelle Habano. Le même détaillant cite Gran Honduras et Guillermo Rico comme autres noms, que l''on ne trouverait pas, dit-il, dans les boutiques américaines.')),
  `history_en` = IF(LOCATE('In October 2026, the page of the German retailer Cigarworld ', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'In October 2026, the page of the German retailer Cigarworld presents, under the name G.H., cigars by Guillermo Rico, rolled in Danlí, Honduras, and sold in Europe: European law there forbids, the retailer writes, claiming a geographical indication for a product that does not come from there, and the original name evokes Havana. The lines of G.H., Connecticut No. 1, Criollo No. 3 and Corojo No. 5, reuse the three numbers of Gran Habano, where No. 3 is called Habano. The same retailer cites Gran Honduras and Guillermo Rico as other names, which, it says, would not be found in American shops.')),
  `history_es` = IF(LOCATE('En octubre de 2026, la página del minorista alemán Cigarworl', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'En octubre de 2026, la página del minorista alemán Cigarworld presenta bajo el nombre G.H. unos puros de Guillermo Rico, enrollados en Danlí, en Honduras, vendidos en Europa: el derecho europeo prohíbe allí, escribe el minorista, hacer valer una indicación geográfica para un producto que no procede de ese lugar, y el nombre de origen evoca La Habana. Las líneas de G.H., Connecticut No. 1, Criollo No. 3 y Corojo No. 5, retoman los tres números de Gran Habano, donde el No. 3 se llama Habano. El mismo minorista cita Gran Honduras y Guillermo Rico como otros nombres, que no se encontrarían, dice, en las tiendas estadounidenses.')),
  `history_de` = IF(LOCATE('Im Oktober 2026 präsentiert die Seite des deutschen Händlers', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Im Oktober 2026 präsentiert die Seite des deutschen Händlers Cigarworld unter dem Namen G.H. Zigarren von Guillermo Rico, die in Danlí, Honduras, gerollt und in Europa verkauft werden: Das europäische Recht verbiete dort, so der Händler, eine geografische Angabe für ein Produkt geltend zu machen, das nicht von dort stammt, und der ursprüngliche Name erinnert an Havanna. Die Linien von G.H., Connecticut No. 1, Criollo No. 3 und Corojo No. 5, übernehmen die drei Nummern von Gran Habano, wo die No. 3 Habano heißt. Derselbe Händler nennt Gran Honduras und Guillermo Rico als weitere Namen, die man, wie er sagt, in amerikanischen Geschäften nicht finden würde.')),
  `history_zh` = IF(LOCATE('2026年十月，德国零售商Cigarworld的页面以G.H.之名展示Guillermo Rico的雪茄，这些雪茄在洪都', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '2026年十月，德国零售商Cigarworld的页面以G.H.之名展示Guillermo Rico的雪茄，这些雪茄在洪都拉斯的Danlí卷制，在欧洲销售：该零售商写道，欧洲法律在当地禁止对并非产自该产地的产品主张地理标志，而原名让人联想到哈瓦那。G.H.的各条产品线Connecticut No. 1、Criollo No. 3和Corojo No. 5，沿用了Gran Habano的三个编号，其中No. 3名为Habano。同一家零售商还列出Gran Honduras和Guillermo Rico作为另外的名称，据其所述，这些名称在美国的商店里是找不到的。')),
  `history_ar` = IF(LOCATE('في أكتوبر 2026 تعرض صفحة تاجر التجزئة الألماني Cigarworld تح', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'في أكتوبر 2026 تعرض صفحة تاجر التجزئة الألماني Cigarworld تحت اسم G.H. سيجارات من Guillermo Rico، تُلَفّ في Danlí بهندوراس وتُباع في أوروبا: فالقانون الأوروبي يمنع هناك، كما يكتب التاجر، التمسك بمؤشر جغرافي لمنتج لا يأتي من ذلك المكان، ويوحي الاسم الأصلي بهافانا. وتستعيد خطوط G.H.، Connecticut No. 1 وCriollo No. 3 وCorojo No. 5، الأرقام الثلاثة الخاصة بـ Gran Habano، حيث يُسمّى No. 3 باسم Habano. ويذكر تاجر التجزئة نفسه Gran Honduras وGuillermo Rico بوصفهما اسمين آخرين لن تجدهما، كما يقول، في المتاجر الأمريكية.')),
  `gamme` = '[{"name":"Connecticut No. 1","color":"#C9A96E","force":"Mild","story":"Le premier des trois chiffres de 2003 : doux, cape Connecticut.","vitolas":[],"wrapper":"Connecticut"},{"name":"Habano No. 3","color":"#8B5A2B","force":"Medium","story":"Le médian.","vitolas":[],"wrapper":"Habano"},{"name":"Corojo No. 5","color":"#7A2E1E","force":"Full","story":"Le poivré. Le Corojo, comme chez J. Fuego, est la feuille des maisons qui veulent du caractère.","vitolas":[],"wrapper":"Corojo"},{"name":"3 Siglos","color":"#5B3A29","force":"Medium-Full","story":"Trois siècles — le nom dit la prétention, quatre ans après la marque.","vitolas":[],"wrapper":"Non divulguée"},{"name":"GR Specials Red Label","color":"#A0522D","force":"Full","wrapper":"Corojo du Nicaragua","vitolas":[],"story":"Bundle de George A. Rico, fils de Guillermo, avec qui il a créé Gran Habano ; la bague porte la mention Hecho a Mano, d''après ghcigars.com. Selon Atlantic Cigar : cape corojo nicaraguayenne, sous-cape hondurienne, tripe nicaraguayenne et mexicaine, force corsée, en Gran Robusto 6 x 54 ; Cigarplace ajoute un Robusto 5 x 50, fait au Honduras."}]',
  `gamme_en` = '[{"name":"Connecticut No. 1","color":"#C9A96E","force":"Mild","story":"The first of the three numbers of 2003: mild, Connecticut wrapper.","vitolas":[],"wrapper":"Connecticut"},{"name":"Habano No. 3","color":"#8B5A2B","force":"Medium","story":"The middle one.","vitolas":[],"wrapper":"Habano"},{"name":"Corojo No. 5","color":"#7A2E1E","force":"Full","story":"The peppery one. Corojo, as at J. Fuego, is the leaf of houses that want character.","vitolas":[],"wrapper":"Corojo"},{"name":"3 Siglos","color":"#5B3A29","force":"Medium-Full","story":"Three centuries — the name states the ambition, four years after the brand.","vitolas":[],"wrapper":"Undisclosed"},{"name":"GR Specials Red Label","color":"#A0522D","force":"Full","wrapper":"Nicaraguan Corojo","vitolas":[],"story":"Bundle by George A. Rico, son of Guillermo, with whom he created Gran Habano; the band bears the words Hecho a Mano, according to ghcigars.com. According to Atlantic Cigar: Nicaraguan corojo wrapper, Honduran binder, Nicaraguan and Mexican filler, full strength, in Gran Robusto 6 x 54; Cigarplace adds a Robusto 5 x 50, made in Honduras."}]',
  `gamme_es` = '[{"name":"Connecticut No. 1","color":"#C9A96E","force":"Mild","story":"El primero de los tres números de 2003: suave, capa Connecticut.","vitolas":[],"wrapper":"Connecticut"},{"name":"Habano No. 3","color":"#8B5A2B","force":"Medium","story":"El del medio.","vitolas":[],"wrapper":"Habano"},{"name":"Corojo No. 5","color":"#7A2E1E","force":"Full","story":"El picante. El Corojo, como en J. Fuego, es la hoja de las casas que quieren carácter.","vitolas":[],"wrapper":"Corojo"},{"name":"3 Siglos","color":"#5B3A29","force":"Medium-Full","story":"Tres siglos — el nombre dice la pretensión, cuatro años después de la marca.","vitolas":[],"wrapper":"No divulgada"},{"name":"GR Specials Red Label","color":"#A0522D","force":"Full","wrapper":"Corojo de Nicaragua","vitolas":[],"story":"Bundle de George A. Rico, hijo de Guillermo, con quien creó Gran Habano; la anilla lleva la mención Hecho a Mano, según ghcigars.com. Según Atlantic Cigar: capa corojo nicaragüense, capote hondureño, tripa nicaragüense y mexicana, fuerza fuerte, en Gran Robusto 6 x 54; Cigarplace añade un Robusto 5 x 50, hecho en Honduras."}]',
  `gamme_de` = '[{"name":"Connecticut No. 1","color":"#C9A96E","force":"Mild","story":"Die erste der drei Ziffern von 2003: mild, Connecticut-Deckblatt.","vitolas":[],"wrapper":"Connecticut"},{"name":"Habano No. 3","color":"#8B5A2B","force":"Medium","story":"Die mittlere.","vitolas":[],"wrapper":"Habano"},{"name":"Corojo No. 5","color":"#7A2E1E","force":"Full","story":"Die pfeffrige. Corojo ist, wie bei J. Fuego, das Blatt der Häuser, die Charakter wollen.","vitolas":[],"wrapper":"Corojo"},{"name":"3 Siglos","color":"#5B3A29","force":"Medium-Full","story":"Drei Jahrhunderte — der Name sagt den Anspruch, vier Jahre nach der Marke.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"GR Specials Red Label","color":"#A0522D","force":"Full","wrapper":"Corojo aus Nicaragua","vitolas":[],"story":"Bundle von George A. Rico, dem Sohn von Guillermo, mit dem er Gran Habano gegründet hat; die Bauchbinde trägt den Vermerk Hecho a Mano, laut ghcigars.com. Laut Atlantic Cigar: nicaraguanisches Corojo-Deckblatt, honduranisches Umblatt, nicaraguanische und mexikanische Einlage, Stärke kräftig, in Gran Robusto 6 x 54; Cigarplace führt zusätzlich einen Robusto 5 x 50 auf, in Honduras gefertigt."}]',
  `gamme_zh` = '[{"name":"Connecticut No. 1","color":"#C9A96E","force":"Mild","story":"2003年三个数字中的第一个：温和，康涅狄格茄衣。","vitolas":[],"wrapper":"Connecticut"},{"name":"Habano No. 3","color":"#8B5A2B","force":"Medium","story":"居中的一款。","vitolas":[],"wrapper":"Habano"},{"name":"Corojo No. 5","color":"#7A2E1E","force":"Full","story":"辛辣的一款。科罗霍，如 J. Fuego 家一样，是想要个性的公司所选的烟叶。","vitolas":[],"wrapper":"Corojo"},{"name":"3 Siglos","color":"#5B3A29","force":"Medium-Full","story":"三个世纪——名字道出了志向，品牌问世四年之后。","vitolas":[],"wrapper":"未公开"},{"name":"GR Specials Red Label","color":"#A0522D","force":"Full","wrapper":"尼加拉瓜Corojo","vitolas":[],"story":"George A. Rico的Bundle，他是Guillermo之子，与其父共同创立了Gran Habano；据ghcigars.com，雪茄标上印有Hecho a Mano字样。据Atlantic Cigar，茄衣为尼加拉瓜corojo，茄套为洪都拉斯所产，茄芯为尼加拉瓜与墨西哥所产，烟力浓郁，规格为Gran Robusto 6 x 54；据Cigarplace，另有Robusto 5 x 50，在洪都拉斯制造。"}]',
  `gamme_ar` = '[{"name":"Connecticut No. 1","color":"#C9A96E","force":"Mild","story":"الأوّل من أرقام 2003 الثلاثة: خفيف، بغلاف كونيتيكت.","vitolas":[],"wrapper":"Connecticut"},{"name":"Habano No. 3","color":"#8B5A2B","force":"Medium","story":"المتوسّط.","vitolas":[],"wrapper":"Habano"},{"name":"Corojo No. 5","color":"#7A2E1E","force":"Full","story":"الفلفليّ. والكوروخو، كما لدى J. Fuego، ورقة الدور التي تريد الطبع.","vitolas":[],"wrapper":"Corojo"},{"name":"3 Siglos","color":"#5B3A29","force":"Medium-Full","story":"ثلاثة قرون — الاسم يقول الطموح، بعد أربع سنوات من العلامة.","vitolas":[],"wrapper":"غير معلن"},{"name":"GR Specials Red Label","color":"#A0522D","force":"Full","wrapper":"Corojo من نيكاراغوا","vitolas":[],"story":"Bundle من George A. Rico، ابن Guillermo الذي أسّس معه Gran Habano؛ يحمل الشريط عبارة Hecho a Mano بحسب ghcigars.com. بحسب Atlantic Cigar: غلاف خارجي corojo نيكاراغوي، ورابط هندوراسي، وحشوة نيكاراغوية ومكسيكية، وقوة قوية، بمقاس Gran Robusto 6 x 54؛ وتضيف Cigarplace مقاس Robusto 5 x 50 صُنع في هندوراس."}]',
  `mentions` = '["G.H."]',
