-- ── J.C. Newman — gamme : Havana Q, The American ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","story":"Un nom de la maison des années 1930, relancé. Roulée à PENSA, la fabrique de la famille à Estelí, où elle a été rapatriée d''une autre fabrique.","vitolas":[],"wrapper":"Habano d''Équateur"},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","story":"La perle de la mer — une ligne de PENSA, ajoutée peu après l''ouverture de 2011.","vitolas":[],"wrapper":"Connecticut d''Équateur"},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","story":"L''un des deux cigares avec lesquels PENSA a ouvert en 2011, avec El Baton. Le cigare de volume de la fabrique.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Havana Q","color":"#8B5A2B","force":"Medium","wrapper":"Graine havane d''Équateur","vitolas":[],"story":"Présentée en janvier 2021 par J.C. Newman comme une cousine de Quorum, à plus gros calibres et en sacs refermables de vingt, d''après Cigar Coop. Cape de graine havane cultivée à Guayas, en Équateur, sous-cape et tripe nicaraguayennes, force moyenne selon la maison, roulée à PENSA en Double Robusto 5 x 56, Double Toro 6 x 54, Double Churchill 7 x 52 et Double Grande 6 x 60."},{"name":"The American","color":"#8B5A2B","force":null,"wrapper":"Florida Sun Grown","vitolas":[],"story":"Marque dont la maison dit qu''elle fut la première roulée à El Reloj, à l''ouverture de l''usine en 1910, relancée à la main en 2019, à l''approche des 125 ans de J.C. Newman : cape Florida Sun Grown, sous-cape Connecticut Broadleaf, tripe de Connecticut Havana avec des tabacs de mennonites de Pennsylvanie. En octobre 2026, le détaillant Corona Cigar vend une édition 250th, pour les 250 ans de l''indépendance américaine."}]',
  `gamme_en` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","story":"A house name of the 1930s, revived. Rolled at PENSA, the family''s factory in Estelí, where it was brought back from another factory.","vitolas":[],"wrapper":"Ecuadorian Habano"},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","story":"The pearl of the sea — a PENSA line, added shortly after the 2011 opening.","vitolas":[],"wrapper":"Ecuadorian Connecticut"},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","story":"One of the two cigars with which PENSA opened in 2011, with El Baton. The factory''s volume cigar.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Havana Q","color":"#8B5A2B","force":"Medium","wrapper":"Ecuadorian Havana seed","vitolas":[],"story":"Presented in January 2021 by J.C. Newman as a cousin of Quorum, with larger gauges and in resealable bags of twenty, according to Cigar Coop. Wrapper of Havana-seed tobacco grown in Guayas, Ecuador, Nicaraguan binder and filler, strength medium according to the company, rolled at PENSA in Double Robusto 5 x 56, Double Toro 6 x 54, Double Churchill 7 x 52 and Double Grande 6 x 60."},{"name":"The American","color":"#8B5A2B","force":null,"wrapper":"Florida Sun Grown","vitolas":[],"story":"Brand which, according to the company, was the first rolled at El Reloj, when the factory opened in 1910, relaunched as a hand-rolled cigar in 2019 ahead of J.C. Newman''s 125 years: Florida Sun Grown wrapper, Connecticut Broadleaf binder, Connecticut Havana filler with Pennsylvania Mennonite tobaccos. In October 2026, the retailer Corona Cigar sells a 250th edition, for the 250 years of American independence."}]',
  `gamme_es` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","story":"Un nombre de la casa de los años 1930, relanzado. Liada en PENSA, la fábrica de la familia en Estelí, adonde fue repatriada desde otra fábrica.","vitolas":[],"wrapper":"Habano de Ecuador"},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","story":"La perla del mar — una línea de PENSA, añadida poco después de la apertura de 2011.","vitolas":[],"wrapper":"Connecticut de Ecuador"},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","story":"Uno de los dos puros con los que PENSA abrió en 2011, con El Baton. El puro de volumen de la fábrica.","vitolas":[],"wrapper":"No divulgada"},{"name":"Havana Q","color":"#8B5A2B","force":"Medium","wrapper":"Semilla habana de Ecuador","vitolas":[],"story":"Presentada en enero de 2021 por J.C. Newman como prima de Quorum, de calibres mayores y en bolsas resellables de veinte, según Cigar Coop. Capa de semilla habana cultivada en Guayas, en Ecuador, capote y tripa nicaragüenses, fuerza medium según la casa, enrollada en PENSA en Double Robusto 5 x 56, Double Toro 6 x 54, Double Churchill 7 x 52 y Double Grande 6 x 60."},{"name":"The American","color":"#8B5A2B","force":null,"wrapper":"Florida Sun Grown","vitolas":[],"story":"Marca que, según la casa, fue la primera enrollada en El Reloj, cuando la fábrica abrió en 1910, relanzada a mano en 2019, a las puertas de los 125 años de J.C. Newman: capa Florida Sun Grown, capote Connecticut Broadleaf, tripa de Connecticut Havana con tabacos de menonitas de Pensilvania. En octubre de 2026, el minorista Corona Cigar vende una edición 250th, por los 250 años de la independencia estadounidense."}]',
  `gamme_de` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","story":"Ein Hausname der 1930er, wiederbelebt. Bei PENSA gerollt, der Fabrik der Familie in Estelí, wohin sie aus einer anderen Fabrik zurückgeholt wurde.","vitolas":[],"wrapper":"Ecuadorianisches Habano"},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","story":"Die Perle des Meeres — eine PENSA-Linie, kurz nach der Eröffnung 2011 hinzugefügt.","vitolas":[],"wrapper":"Ecuadorianisches Connecticut"},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","story":"Eine der beiden Zigarren, mit denen PENSA 2011 eröffnete, mit El Baton. Die Mengenzigarre der Fabrik.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Havana Q","color":"#8B5A2B","force":"Medium","wrapper":"Havanna-Saat aus Ecuador","vitolas":[],"story":"Im Januar 2021 von J.C. Newman als Cousine von Quorum vorgestellt, mit größeren Ringmaßen und in wiederverschließbaren Beuteln zu zwanzig, laut Cigar Coop. Deckblatt aus in Guayas, Ecuador, angebauter Havanna-Saat, nicaraguanisches Umblatt und nicaraguanische Einlage, Stärke medium laut Haus, bei PENSA gerollt in Double Robusto 5 x 56, Double Toro 6 x 54, Double Churchill 7 x 52 und Double Grande 6 x 60."},{"name":"The American","color":"#8B5A2B","force":null,"wrapper":"Florida Sun Grown","vitolas":[],"story":"Marke, die laut Angabe des Hauses als erste bei El Reloj gerollt wurde, bei der Eröffnung der Fabrik 1910, und 2019 von Hand neu aufgelegt wurde, im Vorfeld der 125 Jahre von J.C. Newman: Deckblatt Florida Sun Grown, Umblatt Connecticut Broadleaf, Einlage aus Connecticut Havana mit Tabaken von Mennoniten aus Pennsylvania. Im Oktober 2026 verkauft der Einzelhändler Corona Cigar eine Edition 250th, zu den 250 Jahren der amerikanischen Unabhängigkeit."}]',
  `gamme_zh` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","story":"家族1930年代的一个旧名，重新启用。在家族位于埃斯特利的 PENSA 厂卷制，是从另一家工厂迁回来的。","vitolas":[],"wrapper":"厄瓜多尔 Habano"},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","story":"海之珍珠——PENSA 的一条线，在2011年开厂后不久加入。","vitolas":[],"wrapper":"厄瓜多尔康涅狄格"},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","story":"PENSA 2011年开厂时的两支雪茄之一，另一支是 El Baton。工厂的走量雪茄。","vitolas":[],"wrapper":"未公开"},{"name":"Havana Q","color":"#8B5A2B","force":"Medium","wrapper":"厄瓜多尔哈瓦那种子","vitolas":[],"story":"据Cigar Coop，J.C. Newman于2021年一月将其作为Quorum的表亲推出，环径更大，采用可重复封口的袋装，每袋二十支。茄衣采用在厄瓜多尔Guayas种植的哈瓦那种子，茄套与茄芯均为尼加拉瓜所产，据该公司，烟力为medium，在PENSA卷制，规格为Double Robusto 5 x 56、Double Toro 6 x 54、Double Churchill 7 x 52和Double Grande 6 x 60。"},{"name":"The American","color":"#8B5A2B","force":null,"wrapper":"Florida Sun Grown","vitolas":[],"story":"据该公司，该品牌是首款在El Reloj卷制的雪茄品牌，始于1910年工厂开业之际；2019年以手工方式重新推出，临近J.C. Newman的125周年：茄衣为Florida Sun Grown，茄套为Connecticut Broadleaf，茄芯为Connecticut Havana，并配有宾夕法尼亚州门诺派教徒的烟叶。2026年十月，零售商Corona Cigar销售250th版，为纪念美国独立250年。"}]',
  `gamme_ar` = '[{"name":"Brick House","color":"#8B3A1E","force":"Medium-Full","story":"اسمٌ من أسماء الدار في الثلاثينيات، أُعيد إحياؤه. تُلفّ في PENSA، مصنع العائلة في إستيلي، حيث أُعيدت من مصنع آخر.","vitolas":[],"wrapper":"هابانو إكوادوري"},{"name":"Perla del Mar","color":"#C9A96E","force":"Medium","story":"لؤلؤة البحر — خطّ من PENSA، أُضيف بُعيد افتتاح 2011.","vitolas":[],"wrapper":"كونيتيكت إكوادوري"},{"name":"Quorum","color":"#5B3A29","force":"Mild-Medium","story":"أحد السيجارين اللذين افتتحت بهما PENSA سنة 2011، مع El Baton. سيجار الكمّية في المصنع.","vitolas":[],"wrapper":"غير معلن"},{"name":"Havana Q","color":"#8B5A2B","force":"Medium","wrapper":"بذور هافانا من الإكوادور","vitolas":[],"story":"قدّمتها J.C. Newman في يناير 2021 بوصفها ابنة عمّ لـ Quorum، بأقطار أكبر من أقطار Quorum وفي أكياس قابلة لإعادة الإغلاق، بواقع عشرين في الكيس، بحسب Cigar Coop. غلاف خارجي من بذور هافانا مزروعة في Guayas بالإكوادور، ورابط وحشوة نيكاراغويان، وقوة medium بحسب الشركة، تُلَفّ في PENSA بمقاسات Double Robusto 5 x 56 وDouble Toro 6 x 54 وDouble Churchill 7 x 52 وDouble Grande 6 x 60."},{"name":"The American","color":"#8B5A2B","force":null,"wrapper":"Florida Sun Grown","vitolas":[],"story":"علامة تقول الشركة إنها كانت الأولى التي تُلَفّ في El Reloj، عند افتتاح المصنع عام 1910، وأُعيد إطلاقها يدويًا في 2019، مع اقتراب مرور 125 عامًا على J.C. Newman: غلاف خارجي Florida Sun Grown، ورابط Connecticut Broadleaf، وحشوة Connecticut Havana مع تبغ من المينونايت في بنسلفانيا. وفي أكتوبر 2026 يبيع تاجر التجزئة Corona Cigar إصدار 250th، بمناسبة 250 عامًا على الاستقلال الأمريكي."}]',
  `source` = IF(LOCATE('jcnewman.com « Havana Q » (octobre 2026 : cape havane d''Équa', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'jcnewman.com « Havana Q » (octobre 2026 : cape havane d''Équateur, région de Guayas, sous-cape et tripe nicaraguayennes, force moyenne, quatre formats, usine PENSA, cigares entièrement faits à la main) ; cigar-coop.com « Cigar News: JC Newman Cigar Company Announces Havana Q » (13 janvier 2021 : cousine de Quorum, calibres plus gros, sacs refermables de vingt, expédition en janvier 2021, PENSA) ; jcnewman.com « The American Cigar » (octobre 2026 : roulée à la main aux États-Unis, première marque roulée à El Reloj en 1910, cape de Floride, sous-cape du Connecticut, tripe du Connecticut et de Pennsylvanie) ; jcnewman.com « The American Cigar Launch » (31 mai 2019 : soirées de lancement ; cape Florida Sun Grown, sous-cape Connecticut Broadleaf, tripe de Connecticut Havana et de tabacs mennonites de Lancaster ; roulée à la main à El Reloj, avant les 125 ans de la maison) ; coronacigar.com « The American by J.C. Newman 250th » (octobre 2026 : édition limitée 2026, roulée à la main à El Reloj)')),
  `updated_at` = NOW()
 WHERE `name` = 'J.C. Newman';

-- ── Joya de Nicaragua — paragraphe : Bentley ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Bentley est un autre nom que la maison roule sans le posséde', `history`) > 0, `history`, CONCAT(`history`, '

', 'Bentley est un autre nom que la maison roule sans le posséder. C''est la marque de Bentley Tobacco, entreprise de la famille Schuster dont Cigar Coop fait remonter les origines à 1878, comme fabricant de pipes. Joya de Nicaragua en roule les cigares : le White, à cape Connecticut Shade, et le Green, à cape rosado d''Équateur, tous deux sur sous-cape et tripe nicaraguayennes. Bentley Tobacco a fait en 2025 son premier PCA, avec une division américaine nouvellement lancée ; en octobre 2026, un détaillant liste encore les deux éditions.')),
  `history_en` = IF(LOCATE('Bentley is another name that the company rolls without ownin', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Bentley is another name that the company rolls without owning it. It is the brand of Bentley Tobacco, a company of the Schuster family whose origins Cigar Coop traces back to 1878, as a pipe maker. Joya de Nicaragua rolls the brand''s cigars: the White, with a Connecticut Shade wrapper, and the Green, with an Ecuadorian rosado wrapper, both over a Nicaraguan binder and filler. Bentley Tobacco made its first PCA in 2025, with a newly launched American division; in October 2026, a retailer still lists both editions.')),
  `history_es` = IF(LOCATE('Bentley es otro nombre que la casa enrolla sin poseerlo. Es ', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Bentley es otro nombre que la casa enrolla sin poseerlo. Es la marca de Bentley Tobacco, empresa de la familia Schuster cuyos orígenes Cigar Coop hace remontar a 1878, como fabricante de pipas. Joya de Nicaragua enrolla los puros de la marca: el White, con capa Connecticut Shade, y el Green, con capa rosado de Ecuador, ambos sobre capote y tripa nicaragüenses. Bentley Tobacco hizo en 2025 su primer PCA, con una división estadounidense recién lanzada; en octubre de 2026, un minorista todavía lista las dos ediciones.')),
  `history_de` = IF(LOCATE('Bentley ist ein weiterer Name, den das Haus rollt, ohne ihn ', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Bentley ist ein weiterer Name, den das Haus rollt, ohne ihn zu besitzen. Es ist die Marke von Bentley Tobacco, einem Unternehmen der Familie Schuster, dessen Ursprünge Cigar Coop auf 1878 zurückführt, als Pfeifenhersteller. Joya de Nicaragua rollt die Zigarren der Marke: den White mit Deckblatt Connecticut Shade und den Green mit Deckblatt rosado aus Ecuador, beide über einem nicaraguanischen Umblatt und einer nicaraguanischen Einlage. Bentley Tobacco nahm 2025 zum ersten Mal an der PCA teil, mit einer neu gestarteten amerikanischen Division; im Oktober 2026 führt ein Einzelhändler weiterhin beide Editionen auf.')),
  `history_zh` = IF(LOCATE('Bentley是该公司代为卷制而并不拥有的另一个名称。它是Bentley Tobacco的品牌，这是一家Schuster', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'Bentley是该公司代为卷制而并不拥有的另一个名称。它是Bentley Tobacco的品牌，这是一家Schuster家族的企业，据Cigar Coop，其渊源可追溯至1878年，当时是一家烟斗制造商。Joya de Nicaragua为该品牌卷制雪茄：White采用Connecticut Shade茄衣，Green采用厄瓜多尔rosado茄衣，两者的茄套与茄芯均为尼加拉瓜所产。Bentley Tobacco于2025年首次参加PCA，并有一个新近推出的美国分部；2026年十月，仍有一家零售商列出这两个版本。')),
  `history_ar` = IF(LOCATE('Bentley اسم آخر تلفّ الشركة سيجاره دون أن تملكه. وهو علامة B', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'Bentley اسم آخر تلفّ الشركة سيجاره دون أن تملكه. وهو علامة Bentley Tobacco، شركة تعود إلى عائلة Schuster تُرجِع Cigar Coop أصولها إلى 1878، بوصفها صانعة غلايين. وتلفّ Joya de Nicaragua سيجارات العلامة: White بغلاف خارجي Connecticut Shade، وGreen بغلاف خارجي rosado من الإكوادور، وكلاهما فوق رابط وحشوة نيكاراغويين. وقد شاركت Bentley Tobacco في 2025 في PCA لأول مرة، مع قسم أمريكي أُطلق حديثًا؛ وفي أكتوبر 2026 ما زال تاجر تجزئة يدرج الإصدارين.')),
  `mentions` = '["Black Swan","Bentley"]',
  `source` = IF(LOCATE('cigar-coop.com « PCA 2025: Bentley Tobacco | USA » (15 mai 2', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « PCA 2025: Bentley Tobacco | USA » (15 mai 2025 : Bentley Tobacco, issue d''un fabricant de pipes de 1878, dirigée par la famille Schuster ; division américaine ; White à cape Connecticut Shade et Green à cape rosado d''Équateur, sous-cape et tripe nicaraguayennes ; tous les cigares roulés à la fabrique Joya de Nicaragua ; premier PCA de Bentley Tobacco) ; cigarsdirect.com « Bentley Green Edition Churchill » (octobre 2026 : cape rosado d''Équateur, sous-cape et tripe de la vallée de Jalapa, en stock) ; luxurycigarclub.com « Bentley White Edition » (octobre 2026 : cape Connecticut d''Équateur, sous-cape et tripe nicaraguayennes, produit avec la famille Schuster)')),
  `updated_at` = NOW()
 WHERE `name` = 'Joya de Nicaragua';

-- ── Kelner Boutique Factory — paragraphe : Centaur Cigars ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Centaur Cigars est une autre marque que la fabrique roule po', `history`) > 0, `history`, CONCAT(`history`, '

', 'Centaur Cigars est une autre marque que la fabrique roule pour un tiers : le nom est celui de Tobias Forst, qui a pris pour thème la mythologie grecque. En octobre 2026, ses cigares, réunis en Hero Series, portent des noms de héros, Cheiron, Achilles, Odysseus, Jason, Perseus et Kronos, et des détaillants allemands les vendent en Toro, avec un Toro Grande pour Kronos. Ils sont roulés à la main, chez Hendrik Kelner Jr., à la Kelner Boutique Factory, à Santiago de los Caballeros.')),
  `history_en` = IF(LOCATE('Centaur Cigars is another brand that the factory rolls for a', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Centaur Cigars is another brand that the factory rolls for a third party: the name is that of Tobias Forst, who took Greek mythology as the theme. In October 2026, its cigars, grouped in the Hero Series, bear the names of heroes, Cheiron, Achilles, Odysseus, Jason, Perseus and Kronos, and German retailers sell them in Toro, with a Toro Grande for Kronos. They are hand-rolled at Hendrik Kelner Jr., at the Kelner Boutique Factory, in Santiago de los Caballeros.')),
  `history_es` = IF(LOCATE('Centaur Cigars es otra marca que la fábrica enrolla para un ', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Centaur Cigars es otra marca que la fábrica enrolla para un tercero: el nombre es el de Tobias Forst, que tomó como tema la mitología griega. En octubre de 2026, sus puros, reunidos en la Hero Series, llevan nombres de héroes, Cheiron, Achilles, Odysseus, Jason, Perseus y Kronos, y minoristas alemanes los venden en Toro, con un Toro Grande para Kronos. Se enrollan a mano, en Hendrik Kelner Jr., en la Kelner Boutique Factory, en Santiago de los Caballeros.')),
  `history_de` = IF(LOCATE('Centaur Cigars ist eine weitere Marke, die die Fabrik für ei', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Centaur Cigars ist eine weitere Marke, die die Fabrik für einen Dritten rollt: Der Name ist der von Tobias Forst, der die griechische Mythologie zum Thema genommen hat. Im Oktober 2026 tragen ihre Zigarren, in der Hero Series zusammengefasst, Heldennamen, Cheiron, Achilles, Odysseus, Jason, Perseus und Kronos, und deutsche Einzelhändler verkaufen sie im Toro, mit einem Toro Grande für Kronos. Sie werden von Hand gerollt, bei Hendrik Kelner Jr., in der Kelner Boutique Factory in Santiago de los Caballeros.')),
  `history_zh` = IF(LOCATE('Centaur Cigars是该工厂为第三方卷制的另一个品牌：该名称是Tobias Forst的，他以希腊神话为主题。2', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'Centaur Cigars是该工厂为第三方卷制的另一个品牌：该名称是Tobias Forst的，他以希腊神话为主题。2026年十月，其雪茄归入Hero Series，以英雄命名，包括Cheiron、Achilles、Odysseus、Jason、Perseus和Kronos，德国零售商以Toro规格销售，Kronos则为Toro Grande。它们在Hendrik Kelner Jr.处，于Kelner Boutique Factory手工卷制，地点为Santiago de los Caballeros。')),
  `history_ar` = IF(LOCATE('Centaur Cigars علامة أخرى يلفّها المصنع لحساب طرف ثالث: الاس', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'Centaur Cigars علامة أخرى يلفّها المصنع لحساب طرف ثالث: الاسم يخص Tobias Forst، الذي اتخذ الميثولوجيا اليونانية موضوعًا. وفي أكتوبر 2026 تحمل سيجاراتها، المجمّعة في Hero Series، أسماء أبطال، Cheiron وAchilles وOdysseus وJason وPerseus وKronos، ويبيعها تجار تجزئة ألمان بمقاس Toro، مع Toro Grande لـ Kronos. وهي تُلَفّ يدويًا لدى Hendrik Kelner Jr.، في Kelner Boutique Factory، في Santiago de los Caballeros.')),
  `mentions` = '["Centaur Cigars"]',
  `source` = IF(LOCATE('cigarworld.de « Centaur: Buy Cigars » (octobre 2026 : Centau', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigarworld.de « Centaur: Buy Cigars » (octobre 2026 : Centaur Cigars, marque menée par Tobias Forst, mythologie grecque, produite à la Tabacalera Hendrik Kelner Jr., Santiago de los Caballeros) ; cigarworld.de « Buy Centaur Cigars Hero Series cigars » (octobre 2026 : propriétaire de la marque Tobias Forst, six mélanges Cheiron, Achilles, Odysseus, Jason, Perseus, Kronos, en Toro et Toro Grande pour Kronos, totalmente a mano, produits à la Kelner Boutique Factory par Hendrik Kelner Jr.) ; paul-bugge.com « Centaur Cigars Hero Series Achilles » (octobre 2026 : Achilles produite à la Kelner Boutique Factory, marque dirigée par Tobias Forst)')),
  `updated_at` = NOW()
 WHERE `name` = 'Kelner Boutique Factory';

-- ── Kristoff — paragraphe : Dominican Santiago Selection, R.A. Villamil, Quisqueya ──
UPDATE `brands` SET
  `history` = IF(LOCATE('La Tabacalera von Eicken, à Santiago, ne roule pas que Krist', `history`) > 0, `history`, CONCAT(`history`, '

', 'La Tabacalera von Eicken, à Santiago, ne roule pas que Kristoff. Elle s''appelait Charles Fairmorn, et ce nom reste celui du fabricant sur d''autres marques. En octobre 2026, le détaillant allemand Cigarworld en propose trois qui ne sont pas à Kristoff : Dominican Santiago Selection, série que sa page date de 2003, en longfiller ; Quisqueya et R.A. Villamil, en medium-filler, la Clasico de R.A. Villamil étant datée de 2007. Kleinlagel, à Bruchsal, est donné comme distributeur des deux premières.')),
  `history_en` = IF(LOCATE('Tabacalera von Eicken, in Santiago, rolls more than Kristoff', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Tabacalera von Eicken, in Santiago, rolls more than Kristoff alone. It was called Charles Fairmorn, and that name remains that of the manufacturer on other brands. In October 2026, the German retailer Cigarworld offers three that do not belong to Kristoff: Dominican Santiago Selection, a series whose page dates it to 2003, in longfiller; Quisqueya and R.A. Villamil, in medium-filler, the R.A. Villamil Clasico being dated 2007. Kleinlagel, in Bruchsal, is given as the distributor of the first two.')),
  `history_es` = IF(LOCATE('La Tabacalera von Eicken, en Santiago, no enrolla solo Krist', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'La Tabacalera von Eicken, en Santiago, no enrolla solo Kristoff. Se llamaba Charles Fairmorn, y ese nombre sigue siendo el del fabricante en otras marcas. En octubre de 2026, el minorista alemán Cigarworld ofrece tres que no son de Kristoff: Dominican Santiago Selection, serie que su página fecha en 2003, en longfiller; Quisqueya y R.A. Villamil, en medium-filler, estando la Clasico de R.A. Villamil fechada en 2007. Kleinlagel, en Bruchsal, figura como distribuidor de las dos primeras.')),
  `history_de` = IF(LOCATE('Die Tabacalera von Eicken in Santiago rollt nicht nur Kristo', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Die Tabacalera von Eicken in Santiago rollt nicht nur Kristoff. Sie hieß Charles Fairmorn, und dieser Name ist bei anderen Marken weiterhin der des Herstellers. Im Oktober 2026 bietet der deutsche Einzelhändler Cigarworld drei an, die nicht zu Kristoff gehören: Dominican Santiago Selection, eine Serie, deren Seite sie auf 2003 datiert, in longfiller; Quisqueya und R.A. Villamil, in medium-filler, wobei die Clasico von R.A. Villamil auf 2007 datiert ist. Kleinlagel in Bruchsal wird als Vertriebspartner der ersten beiden angegeben.')),
  `history_zh` = IF(LOCATE('位于Santiago的Tabacalera von Eicken并非只卷制Kristoff。它曾名为Charles Fa', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '位于Santiago的Tabacalera von Eicken并非只卷制Kristoff。它曾名为Charles Fairmorn，这一名称在其他品牌上仍是制造商的名称。2026年十月，德国零售商Cigarworld提供三个不属于Kristoff的品牌：Dominican Santiago Selection，该系列的页面将其标注为2003年，为longfiller；Quisqueya和R.A. Villamil，为medium-filler，其中R.A. Villamil的Clasico标注为2007年。Kleinlagel位于Bruchsal，被列为前两个的分销商。')),
  `history_ar` = IF(LOCATE('لا تقتصر Tabacalera von Eicken، في Santiago، على لفّ Kristof', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'لا تقتصر Tabacalera von Eicken، في Santiago، على لفّ Kristoff. فقد كانت تُسمّى Charles Fairmorn، ولا يزال هذا الاسم هو اسم المصنّع على علامات أخرى. وفي أكتوبر 2026 يعرض تاجر التجزئة الألماني Cigarworld ثلاث علامات لا تخص Kristoff: Dominican Santiago Selection، وهي سلسلة تؤرّخها صفحتها بعام 2003، من نوع longfiller؛ وQuisqueya وR.A. Villamil، من نوع medium-filler، علمًا أن تاريخ Clasico من R.A. Villamil يعود إلى 2007. ويُذكر Kleinlagel، في Bruchsal، موزّعًا للأوليين.')),
  `mentions` = '["Dominican Santiago Selection","R.A. Villamil","Quisqueya"]',
  `source` = IF(LOCATE('cigarworld.de « Dominican Santiago Selection (DSS) » (octobr', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigarworld.de « Dominican Santiago Selection (DSS) » (octobre 2026 : fabricant Charles Fairmorn dans sa propre usine en République dominicaine, distributeur Kleinlagel à Bruchsal, longfiller roulé à la main, série introduite le 13 avril 2003 selon la page) ; cigarworld.de « Quisqueya Maduro Toro » (octobre 2026 : fabricant Charles Fairmorn S.A., distributeur Kleinlagel, medium-filler roulé à la main, en stock) ; cigarworld.de « Quisqueya Classic Numero Cinco » (octobre 2026 : medium-filler roulé à la main, en stock) ; cigarworld.de « R.A. Villamil Clasico » (octobre 2026 : fabricant Tabacalera by Charles Fairmorn, medium-filler, introduit le 24 janvier 2007 selon la page, en stock) ; cigar-coop.com « Cigar News: Rolando Villamil passes away » (3 février 2022 : Rolando Villamil dirigeait les opérations de la fabrique Tabacalera Von Eicken, la fabrique Charles Fairmorn, où sont roulés Kristoff et Epic)')),
  `updated_at` = NOW()
 WHERE `name` = 'Kristoff';

-- ── La Aroma de Cuba — paragraphe : La Aroma del Caribe ──
UPDATE `brands` SET
  `history` = IF(LOCATE('En Allemagne comme en Suisse, la marque se vend sous le nom ', `history`) > 0, `history`, CONCAT(`history`, '

', 'En Allemagne comme en Suisse, la marque se vend sous le nom La Aroma del Caribe. En octobre 2026, le détaillant allemand Cigarworld la propose sous ce nom, avec My Father Cigars S.A. comme fabricant et M. K. & Söhne, à Rellingen, comme importateur, dans des séries dont Mi Amor. Une page d''analyse de cigare la rattache à Ashton, la marque étant connue aux États-Unis sous le nom La Aroma de Cuba. En Suisse, la Pasion Churchill est indiquée disponible dès mars 2023 chez l''importateur The Royal Cigar Company.')),
  `history_en` = IF(LOCATE('In Germany as in Switzerland, the brand is sold under the na', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

