  `history_es` = IF(LOCATE('Tanto en Alemania como en Suiza, la marca se vende con el no', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Tanto en Alemania como en Suiza, la marca se vende con el nombre La Aroma del Caribe. En octubre de 2026, el minorista alemán Cigarworld la ofrece con ese nombre, con My Father Cigars S.A. como fabricante y M. K. & Söhne, en Rellingen, como importador, en series entre las que figura Mi Amor. Una página de análisis de puros la vincula con Ashton, siendo la marca conocida en Estados Unidos con el nombre La Aroma de Cuba. En Suiza, la Pasion Churchill figura como disponible desde marzo de 2023 en el importador The Royal Cigar Company.')),
  `history_de` = IF(LOCATE('In Deutschland wie in der Schweiz wird die Marke unter dem N', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'In Deutschland wie in der Schweiz wird die Marke unter dem Namen La Aroma del Caribe verkauft. Im Oktober 2026 bietet der deutsche Einzelhändler Cigarworld sie unter diesem Namen an, mit My Father Cigars S.A. als Hersteller und M. K. & Söhne in Rellingen als Importeur, in Serien, darunter Mi Amor. Eine Seite mit einer Zigarrenanalyse ordnet sie Ashton zu, wobei die Marke in den Vereinigten Staaten unter dem Namen La Aroma de Cuba bekannt ist. In der Schweiz wird die Pasion Churchill ab März 2023 beim Importeur The Royal Cigar Company als verfügbar angegeben.')),
  `history_zh` = IF(LOCATE('在德国和瑞士，该品牌以La Aroma del Caribe之名销售。2026年十月，德国零售商Cigarworld以此', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '在德国和瑞士，该品牌以La Aroma del Caribe之名销售。2026年十月，德国零售商Cigarworld以此名称提供该品牌，制造商为My Father Cigars S.A.，进口商为位于Rellingen的M. K. & Söhne，所列系列中有Mi Amor。一个雪茄分析页面将其关联至Ashton，该品牌在美国称为La Aroma de Cuba。在瑞士，Pasion Churchill被标示自2023年三月起可在进口商The Royal Cigar Company处购买。')),
  `history_ar` = IF(LOCATE('في ألمانيا كما في سويسرا تُباع العلامة باسم La Aroma del Car', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'في ألمانيا كما في سويسرا تُباع العلامة باسم La Aroma del Caribe. وفي أكتوبر 2026 يعرضها تاجر التجزئة الألماني Cigarworld بهذا الاسم، مع My Father Cigars S.A. بوصفها الصانع وM. K. & Söhne، في Rellingen، بوصفها المستورد، ضمن سلاسل منها Mi Amor. وتربطها صفحة تحليل لسيجار بـ Ashton، علمًا أن العلامة معروفة في الولايات المتحدة باسم La Aroma de Cuba. وفي سويسرا تُذكر Pasion Churchill متاحةً ابتداءً من مارس 2023 لدى المستورد The Royal Cigar Company.')),
  `mentions` = '["La Aroma del Caribe"]',
  `source` = IF(LOCATE('cigarworld.de « La Aroma del Caribe Connecticut Robusto » (o', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigarworld.de « La Aroma del Caribe Connecticut Robusto » (octobre 2026 : fabricant My Father Cigars S.A., Nicaragua ; importateur M. K. & Söhne GmbH, Rellingen ; longfiller roulé à la main ; au catalogue de la boutique depuis le 21 juillet 2025 selon la page) ; cigarworld.de « La Aroma del Caribe Mi Amor Valentino » (octobre 2026 : fabricant My Father Cigars S.A. ; série Mi Amor, cape San Andrés du Mexique ; en vente) ; cigarsense.com « Cigar Analysis : La Aroma del Caribe (de Cuba) Mi Amor Reserva Maximo » (sans date : marque d''Ashton, fabriquée au Nicaragua, connue aux États-Unis sous le nom La Aroma de Cuba) ; zigarren.zone « La Aroma del Caribe Pasion Churchill » (7 mars 2023, modifié le 21 août 2025 : disponible en Suisse dès le 7 mars 2023, importateur The Royal Cigar Company AG, cigare de Jose Pepin Garcia et Jaime Garcia) ; halfwheel.com « Ashton brings La Aroma del Caribe core line to Europe » (lue par son titre : la ligne de base La Aroma del Caribe arrive en Europe)')),
  `updated_at` = NOW()
 WHERE `name` = 'La Aroma de Cuba';

-- ── La Aurora — paragraphe : Tatiana ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Tatiana n''est pas à La Aurora : c''est la marque de cigares a', `history`) > 0, `history`, CONCAT(`history`, '

', 'Tatiana n''est pas à La Aurora : c''est la marque de cigares aromatisés de Miami Cigar & Co., nommée d''après la fille de ses fondateurs et sortie en 1998 selon la maison. En mai 2024, un site d''actualité du cigare écrit que La Aurora produit l''assemblage du Tatiana Delights, sans arôme ajouté hormis un bout sucré, en Robusto, Toro et Churchill. En août 2026, de nouveaux formats Cappuccino et Amaretto, en 6 x 44 et en tins de dix, étaient expédiés aux détaillants américains.')),
  `history_en` = IF(LOCATE('Tatiana does not belong to La Aurora: it is Miami Cigar & Co', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Tatiana does not belong to La Aurora: it is Miami Cigar & Co.''s brand of flavoured cigars, named after the daughter of its founders and released in 1998 according to the company. In May 2024, a cigar news website wrote that La Aurora produces the blend of the Tatiana Delights, with no added flavour apart from a sweet tip, in Robusto, Toro and Churchill. In August 2026, new Cappuccino and Amaretto formats, in 6 x 44 and in tins of ten, were being shipped to American retailers.')),
  `history_es` = IF(LOCATE('Tatiana no pertenece a La Aurora: es la marca de puros aroma', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Tatiana no pertenece a La Aurora: es la marca de puros aromatizados de Miami Cigar & Co., llamada así por la hija de sus fundadores y lanzada en 1998 según la casa. En mayo de 2024, un sitio de noticias del puro escribe que La Aurora produce la mezcla del Tatiana Delights, sin aroma añadido salvo una punta dulce, en Robusto, Toro y Churchill. En agosto de 2026, nuevos formatos Cappuccino y Amaretto, en 6 x 44 y en tins de diez, se enviaban a minoristas estadounidenses.')),
  `history_de` = IF(LOCATE('Tatiana gehört nicht zu La Aurora: Es ist die Marke aromatis', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Tatiana gehört nicht zu La Aurora: Es ist die Marke aromatisierter Zigarren von Miami Cigar & Co., benannt nach der Tochter ihrer Gründer und laut Angabe des Hauses 1998 erschienen. Im Mai 2024 schreibt eine Nachrichtenseite zur Zigarre, dass La Aurora die Mischung des Tatiana Delights produziert, ohne zugesetztes Aroma bis auf eine gesüßte Spitze, in Robusto, Toro und Churchill. Im August 2026 wurden neue Formate Cappuccino und Amaretto, in 6 x 44 und in Tins zu zehn, an amerikanische Einzelhändler versandt.')),
  `history_zh` = IF(LOCATE('Tatiana并不属于La Aurora：它是Miami Cigar & Co.的调味雪茄品牌，以其创始人之女命名，据该', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'Tatiana并不属于La Aurora：它是Miami Cigar & Co.的调味雪茄品牌，以其创始人之女命名，据该公司称于1998年推出。2024年五月，一家雪茄资讯网站写道，La Aurora生产Tatiana Delights的拼配，除带甜味的一端外不添加香味，规格为Robusto、Toro和Churchill。2026年八月，新规格Cappuccino和Amaretto，即6 x 44和十支装tins，正发往美国零售商。')),
  `history_ar` = IF(LOCATE('Tatiana لا تعود إلى La Aurora: فهي علامة السيجارات المنكّهة ', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'Tatiana لا تعود إلى La Aurora: فهي علامة السيجارات المنكّهة لدى Miami Cigar & Co.، سُمّيت نسبةً إلى ابنة مؤسسيها وصدرت في 1998 بحسب الشركة. وفي مايو 2024 يكتب موقع أخبار السيجار أن La Aurora تنتج توليفة Tatiana Delights، دون نكهة مضافة سوى طرف محلّى، بمقاسات Robusto وToro وChurchill. وفي أغسطس 2026 كانت تُشحن إلى تجار التجزئة الأمريكيين مقاسات جديدة Cappuccino وAmaretto، بمقاس 6 x 44 وفي tins من عشرة.')),
  `mentions` = '["Tatiana"]',
  `source` = IF(LOCATE('miamicigar.com « Our Story » (octobre 2026 : la marque Tatia', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'miamicigar.com « Our Story » (octobre 2026 : la marque Tatiana sort en 1998, Tatiana Wood, fille de la famille, entre dans la maison en 1994 ; la page ne nomme pas de fabrique) ; cigar-coop.com « Tatiana Delights heads to retailers » (29 mai 2024 : La Aurora produit l''assemblage du Tatiana Delights, sans arôme hormis un bout sucré, Robusto, Toro et Churchill en boîtes de 18) ; cigar-coop.com « Miami Cigar & Company shipping Tatiana 25th Anniversary » (23 octobre 2023 : Tatiana, marque aromatisée de Miami Cigar & Company, nommée d''après la fille des fondateurs, édition limitée des 25 ans) ; stogiepress.com « Tatiana Cappuccino and Amaretto in Classic and tin formats are now shipping to retailers » (24 août 2026 : formats 6 x 44 Classic et tins de dix expédiés aux détaillants)')),
  `updated_at` = NOW()
 WHERE `name` = 'La Aurora';

