  `gamme_es` = '[{"name":"Nestor Miranda Collection","color":"#6B4226","force":"Medium-Full","story":"La línea con el nombre del fundador, hecha en My Father en Estelí — la razón de la clasificación de esta ficha.","vitolas":[],"wrapper":"No divulgada"},{"name":"Don Lino","color":"#8B5A2B","force":"Medium","story":"La marca de los inicios, 1989, por el nombre de un hombre de la fábrica de UST en Honduras. Doce millones de puros en 1996, dos años fuera del mercado, rehecha en La Aurora desde 1999.","vitolas":[],"wrapper":"No divulgada"},{"name":"Don Lino Africa","color":"#4A3728","force":"Full","story":"La variante más oscura de la marca de los inicios.","vitolas":[],"wrapper":"No divulgada"},{"name":"Outcast","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Cubra de Brasil","vitolas":[],"story":"Línea presentada en la feria PCA 2025 y enviada a los minoristas en junio de 2025, fabricada en República Dominicana; en octubre de 2026, la casa no nombra la fábrica. Capa brasileña Cubra, híbrido de Corojo de semilla cubana, capote Sumatra de Ecuador y tripa dominicana, en Robusto, Corona Gorda, Toro y Gran Toro según el anuncio de abril de 2025."}]',
  `gamme_de` = '[{"name":"Nestor Miranda Collection","color":"#6B4226","force":"Medium-Full","story":"Die Linie mit dem Namen des Gründers, gefertigt bei My Father in Estelí — der Grund für die Einordnung dieses Eintrags.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Don Lino","color":"#8B5A2B","force":"Medium","story":"Die Marke der Anfänge, 1989, nach einem Mann in der UST-Fabrik in Honduras. Zwölf Millionen Zigarren 1996, zwei Jahre vom Markt, seit 1999 bei La Aurora neu gemacht.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Don Lino Africa","color":"#4A3728","force":"Full","story":"Die dunklere Variante der Gründungsmarke.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Outcast","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Cubra aus Brasilien","vitolas":[],"story":"Linie, die auf der Messe PCA 2025 vorgestellt und im Juni 2025 an den Einzelhandel versandt wurde, hergestellt in der Dominikanischen Republik; im Oktober 2026 nennt das Haus die Fabrik nicht. Brasilianisches Deckblatt Cubra, ein Hybrid des Corojo aus kubanischer Saat, Sumatra-Umblatt aus Ecuador und dominikanische Einlage, in Robusto, Corona Gorda, Toro und Gran Toro laut der Ankündigung vom April 2025."}]',
  `gamme_zh` = '[{"name":"Nestor Miranda Collection","color":"#6B4226","force":"Medium-Full","story":"以创始人命名的系列，在埃斯特利的 My Father 制作——本词条归类的依据。","vitolas":[],"wrapper":"未公开"},{"name":"Don Lino","color":"#8B5A2B","force":"Medium","story":"1989年起家的牌子，取自 UST 洪都拉斯工厂里一个人的名字。1996年一千两百万支，离市两年，1999年起在 La Aurora 重制。","vitolas":[],"wrapper":"未公开"},{"name":"Don Lino Africa","color":"#4A3728","force":"Full","story":"起家牌子的深色变体。","vitolas":[],"wrapper":"未公开"},{"name":"Outcast","color":"#8B5A2B","force":"Mild-Medium","wrapper":"巴西Cubra","vitolas":[],"story":"该产品线在PCA 2025展会上亮相，2025年六月发运给零售商，在多米尼加共和国制造；2026年十月，该公司未点明工厂。茄衣为巴西Cubra，是古巴种子Corojo的杂交品种，茄套为厄瓜多尔Sumatra，茄芯为多米尼加所产，规格为Robusto、Corona Gorda、Toro和Gran Toro，据2025年四月的公告。"}]',
  `gamme_ar` = '[{"name":"Nestor Miranda Collection","color":"#6B4226","force":"Medium-Full","story":"الخطّ الذي يحمل اسم المؤسّس، يُصنع لدى My Father في إستيلي — سبب تصنيف هذه البطاقة.","vitolas":[],"wrapper":"غير معلن"},{"name":"Don Lino","color":"#8B5A2B","force":"Medium","story":"علامة البدايات، 1989، على اسم رجل في مصنع UST بهندوراس. اثنا عشر مليون سيجار سنة 1996، وسنتان خارج السوق، وأُعيد صنعها لدى La Aurora منذ 1999.","vitolas":[],"wrapper":"غير معلن"},{"name":"Don Lino Africa","color":"#4A3728","force":"Full","story":"التنويع الأدكن لعلامة البدايات.","vitolas":[],"wrapper":"غير معلن"},{"name":"Outcast","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Cubra من البرازيل","vitolas":[],"story":"خط قُدّم في معرض PCA 2025 وشُحن إلى تجار التجزئة في يونيو 2025، صُنع في جمهورية الدومينيكان؛ وفي أكتوبر 2026 لا تسمّي الشركة المصنع. غلاف خارجي Cubra برازيلي، هجين من Corojo من بذور كوبية، ورابط Sumatra من الإكوادور، وحشوة دومينيكانية، بمقاسات Robusto وCorona Gorda وToro وGran Toro بحسب إعلان أبريل 2025."}]',
  `source` = IF(LOCATE('cigar-coop.com « Miami Cigar Outcast » (7 avril 2025 : marqu', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « Miami Cigar Outcast » (7 avril 2025 : marque de Miami Cigar and Company, production en République dominicaine, aucune fabrique nommée, cape brésilienne Cubra, liant Sumatra d''Équateur, tripe dominicaine, force douce à moyenne, quatre formats en boîtes de dix, présentation au PCA 2025, expédition prévue en juin 2025) ; enthusiastreport.com « Outcast Cigars is now shipping » (11 juin 2025 : expédiée aux détaillants, distribuée par Miami Cigar & Co.) ; miamicigar.com (octobre 2026 : Outcast figure parmi les quatre marques de la maison, avec Tatiana, Nestor Miranda et Don Lino) ; outcastcigars.com (octobre 2026 : feuilles rares et peu conventionnelles ; aucune fabrique citée)')),
  `updated_at` = NOW()
 WHERE `name` = 'Miami Cigar & Co.';

-- ── My Father — paragraphe : Old Henry Cigars, gamme : Tabacos Baez ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Old Henry Cigars n''est pas une marque de My Father : elle se', `history`) > 0, `history`, CONCAT(`history`, '

', 'Old Henry Cigars n''est pas une marque de My Father : elle se vend chez Holt''s, qui dit le nom celui d''un chien, vieil ami de la maison, et les cigares assemblés à Estelí par José Pepin García et son fils Jaime. En avril 2007, un test les décrit déjà comme un blend de Don Pepin produit pour Holt''s et vendu chez lui seulement. En octobre 2026, la page de Holt''s donne une cape Habano d''Équateur sur des longfillers nicaraguayens, six formats de 5,5 x 50 à 6,5 x 64, et un classique depuis vingt ans.')),
  `history_en` = IF(LOCATE('Old Henry Cigars is not a My Father brand: it is sold at Hol', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Old Henry Cigars is not a My Father brand: it is sold at Holt''s, which gives the name as that of a dog, an old friend of the house, and the cigars as blended in Estelí by José Pepin García and his son Jaime. In April 2007, a review already describes them as a Don Pepin blend made for Holt''s and sold only there. In October 2026, the Holt''s page gives an Ecuadorian Habano wrapper over Nicaraguan longfillers, six sizes from 5.5 x 50 to 6.5 x 64, and a classic of twenty years'' standing.')),
  `history_es` = IF(LOCATE('Old Henry Cigars no es una marca de My Father: se vende en H', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Old Henry Cigars no es una marca de My Father: se vende en Holt''s, que da el nombre como el de un perro, viejo amigo de la casa, y los puros como ensamblados en Estelí por José Pepin García y su hijo Jaime. En abril de 2007, una reseña ya los describe como una mezcla de Don Pepin producida para Holt''s y vendida solo allí. En octubre de 2026, la página de Holt''s da una capa Habano de Ecuador sobre longfillers nicaragüenses, seis formatos de 5,5 x 50 a 6,5 x 64, y un clásico desde hace veinte años.')),
  `history_de` = IF(LOCATE('Old Henry Cigars ist keine Marke von My Father: Sie wird bei', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Old Henry Cigars ist keine Marke von My Father: Sie wird bei Holt''s verkauft, das den Namen als den eines Hundes, eines alten Freundes des Hauses, angibt und die Zigarren als in Estelí von José Pepin García und seinem Sohn Jaime zusammengestellt. Im April 2007 beschreibt ein Test sie bereits als eine Mischung von Don Pepin, die für Holt''s hergestellt und nur dort verkauft wird. Im Oktober 2026 nennt die Seite von Holt''s ein Habano-Deckblatt aus Ecuador über nicaraguanischen longfillers, sechs Formate von 5,5 x 50 bis 6,5 x 64 und einen Klassiker seit zwanzig Jahren.')),
  `history_zh` = IF(LOCATE('Old Henry Cigars并非My Father的品牌：它在Holt''s销售，Holt''s称这一名称取自一条狗，那', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'Old Henry Cigars并非My Father的品牌：它在Holt''s销售，Holt''s称这一名称取自一条狗，那只狗是公司的老朋友，并称这些雪茄由José Pepin García及其子Jaime在Estelí调配。2007年四月，一篇评测已将它们描述为Don Pepin为Holt''s生产、仅在Holt''s销售的拼配。2026年十月，Holt''s的页面给出厄瓜多尔Habano茄衣，配尼加拉瓜longfillers，共六种规格，从5.5 x 50到6.5 x 64，并称其为二十年来的经典。')),
  `history_ar` = IF(LOCATE('Old Henry Cigars ليست علامة تابعة لـ My Father: فهي تُباع لد', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'Old Henry Cigars ليست علامة تابعة لـ My Father: فهي تُباع لدى Holt''s، التي تقول إن الاسم هو اسم كلب، صديق قديم للدار، وإن السيجارات مُوَلّفة في Estelí على يد José Pepin García وابنه Jaime. وفي أبريل 2007 تصفها مراجعة بالفعل بأنها توليفة من Don Pepin أُنتجت لحساب Holt''s وتُباع لديها وحدها. وفي أكتوبر 2026 تذكر صفحة Holt''s غلافًا خارجيًا Habano من الإكوادور فوق longfillers نيكاراغوية، وستة مقاسات من 5,5 x 50 إلى 6,5 x 64، وصنفًا كلاسيكيًا منذ عشرين عامًا.')),
  `gamme` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"Torpedo (52 x 152mm). Assemblage nicaraguayen complexe, cape Habano oscuro d''Équateur. Notes de cèdre rouge, café macchiato, poivre cubèbe. La référence de la maison — chaque lot est attendu comme un millésime.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro d''Équateur"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"Lancé en 2008, le cigare inaugural de la maison. Cape Connecticut naturel d''Équateur sur nicaraguayen. Notes de crème, noisette, épices légères. Malgré son statut de premier essai, le No.1 n''a jamais quitté le catalogue — Pepín avait vu juste dès le début.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut d''Équateur"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"Hommage aux manufactures cubaines d''avant-révolution. Cape maduro Connecticut Broadleaf sur nicaraguayen vieilli. Notes de chocolat noir, café froid, mélasse. Plus douce que la Le Bijou 1922, plus accessible, tout aussi remarquable. L''entrée dans l''univers My Father pour les amateurs de maduro.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","story":"2010 — la ligne au nom du fils, cape broadleaf.","vitolas":[],"wrapper":"Broadleaf du Connecticut"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","story":"2012 — un puro nicaraguayen pressé, cape cultivée au soleil sur les fermes de la famille.","vitolas":[],"wrapper":"Puro nicaraguayen"},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","story":"2012 — la marque de Janny García, la fille de la maison.","vitolas":[],"wrapper":"Broadleaf du Connecticut"},{"name":"El Centurión","color":"#7A2E1E","force":"Full","story":"Une édition limitée de 2007, revenue en ligne régulière en 2013.","vitolas":[],"wrapper":"Habano du Nicaragua"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","wrapper":"Habano du Nicaragua","vitolas":[],"story":"En octobre 2026, le détaillant Cigarsdaily la dit la première marque maison de My Father en short filler (S.F. pour short filler), mais une critique de 2010 décrit un remplissage mixte, environ 70 % de long filler de graine cubaine, fait des chutes de la production de Pepin García. Cape Habano du Nicaragua sur liant et tripe nicaraguayens, en Robusto 5 x 50, vendu à cette date, et en Corona 6 x 46 en 2010."}]',
  `gamme_en` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"Torpedo (52 x 152mm). Complex Nicaraguan blend, Ecuadorian Habano oscuro wrapper. Red cedar, macchiato, cubeb pepper. The house benchmark — each batch is awaited like a vintage.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Ecuadorian Habano Oscuro"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"Launched in 2008, the house''s inaugural cigar. Ecuadorian Connecticut natural wrapper over Nicaraguan. Cream, hazelnut, light spice. For all its status as a first attempt, the No.1 has never left the catalogue — Pepín had it right from the start.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Ecuadorian Connecticut"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"A tribute to the pre-revolution Cuban factories. Connecticut Broadleaf maduro wrapper over aged Nicaraguan. Dark chocolate, cold coffee, molasses. Milder than the Le Bijou 1922, more approachable, every bit as remarkable. The way into the My Father world for maduro lovers.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","story":"2010 — the line in the son''s name, broadleaf wrapper.","vitolas":[],"wrapper":"Connecticut broadleaf"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","story":"2012 — a box-pressed Nicaraguan puro, sun-grown wrapper from the family''s farms.","vitolas":[],"wrapper":"Nicaraguan puro"},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","story":"2012 — the brand of Janny García, the house''s daughter.","vitolas":[],"wrapper":"Connecticut broadleaf"},{"name":"El Centurión","color":"#7A2E1E","force":"Full","story":"A 2007 limited edition, back as a regular line in 2013.","vitolas":[],"wrapper":"Nicaraguan Habano"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","wrapper":"Nicaraguan Habano","vitolas":[],"story":"In October 2026, the retailer Cigarsdaily calls it My Father''s first house brand in short filler (S.F. for short filler), but a 2010 review describes a mixed filler, about 70% long filler of Cuban seed, made from offcuts of Pepin García''s production. Habano wrapper from Nicaragua over Nicaraguan binder and filler, in Robusto 5 x 50, on sale at that date, and in Corona 6 x 46 in 2010."}]',
  `gamme_es` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"Torpedo (52 x 152mm). Liga nicaragüense compleja, capa Habano oscuro de Ecuador. Cedro rojo, macchiato, pimienta cubeba. La referencia de la casa: cada lote se espera como una añada.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro de Ecuador"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"Lanzado en 2008, el puro inaugural de la casa. Capa Connecticut natural de Ecuador sobre nicaragüense. Crema, avellana, especias ligeras. Pese a su condición de primer intento, el No.1 nunca ha salido del catálogo: Pepín acertó desde el principio.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut de Ecuador"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"Homenaje a las manufacturas cubanas de antes de la revolución. Capa maduro Connecticut Broadleaf sobre nicaragüense envejecido. Chocolate negro, café frío, melaza. Más suave que la Le Bijou 1922, más accesible, igual de notable. La puerta de entrada al universo My Father para los aficionados al maduro.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","story":"2010 — la línea con el nombre del hijo, capa broadleaf.","vitolas":[],"wrapper":"Broadleaf de Connecticut"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","story":"2012 — un puro nicaragüense prensado, capa cultivada al sol en las fincas de la familia.","vitolas":[],"wrapper":"Puro nicaragüense"},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","story":"2012 — la marca de Janny García, la hija de la casa.","vitolas":[],"wrapper":"Broadleaf de Connecticut"},{"name":"El Centurión","color":"#7A2E1E","force":"Full","story":"Una edición limitada de 2007, vuelta como línea regular en 2013.","vitolas":[],"wrapper":"Habano de Nicaragua"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","wrapper":"Habano de Nicaragua","vitolas":[],"story":"En octubre de 2026, el minorista Cigarsdaily la presenta como la primera marca de la casa de My Father en short filler, abreviado S.F., pero una reseña de 2010 describe un relleno mixto, de alrededor de un 70 % de longfiller de semilla cubana, hecho con recortes de la producción de Pepin García. Capa Habano de Nicaragua sobre capote y tripa nicaragüenses, en Robusto 5 x 50, a la venta en esa fecha, y en Corona 6 x 46 en 2010."}]',
  `gamme_de` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"Torpedo (52 x 152 mm). Komplexe nicaraguanische Mischung, Deckblatt Habano Oscuro aus Ecuador. Rote Zeder, Macchiato, Kubebenpfeffer. Der Maßstab des Hauses — jede Charge wird wie ein Jahrgang erwartet.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro aus Ecuador"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"2008 lanciert, die erste Zigarre des Hauses. Deckblatt Connecticut Natural aus Ecuador über Nicaraguanischem. Sahne, Haselnuss, leichte Gewürze. Trotz ihres Status als Erstling hat die No.1 den Katalog nie verlassen — Pepín lag von Anfang an richtig.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut aus Ecuador"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"Eine Hommage an die kubanischen Manufakturen vor der Revolution. Deckblatt Connecticut Broadleaf Maduro über gereiftem Nicaragua-Tabak. Zartbitterschokolade, kalter Kaffee, Melasse. Milder als die Le Bijou 1922, zugänglicher, ebenso bemerkenswert. Der Einstieg in die Welt von My Father für Maduro-Liebhaber.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","story":"2010 — die Linie im Namen des Sohnes, Broadleaf-Deckblatt.","vitolas":[],"wrapper":"Connecticut-Broadleaf"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","story":"2012 — ein gepresster nicaraguanischer Puro, sonnengereiftes Deckblatt von den Farmen der Familie.","vitolas":[],"wrapper":"Nicaraguanischer Puro"},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","story":"2012 — die Marke von Janny García, der Tochter des Hauses.","vitolas":[],"wrapper":"Connecticut-Broadleaf"},{"name":"El Centurión","color":"#7A2E1E","force":"Full","story":"Eine limitierte Auflage von 2007, seit 2013 als reguläre Linie zurück.","vitolas":[],"wrapper":"Nicaraguanisches Habano"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","wrapper":"Habano aus Nicaragua","vitolas":[],"story":"Im Oktober 2026 bezeichnet der Einzelhändler Cigarsdaily sie als die erste Hausmarke von My Father mit Shortfiller (S.F. für Short Filler), doch eine Rezension von 2010 beschreibt eine gemischte Einlage, etwa 70 % Longfiller kubanischer Saat, hergestellt aus Produktionsresten von Pepin García. Habano-Deckblatt aus Nicaragua über nicaraguanischem Umblatt und nicaraguanischer Einlage, im Robusto 5 x 50, zu diesem Zeitpunkt im Verkauf, und im Corona 6 x 46 im Jahr 2010."}]',
  `gamme_zh` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"鱼雷型（52 x 152 毫米）。尼加拉瓜复杂配方，厄瓜多尔深色哈瓦那茄衣。红雪松、玛奇朵、荜澄茄。这是这家老号的标杆——每一批都像年份酒一样被等待。","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"厄瓜多尔 Habano Oscuro"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"2008 年推出，是这家老号的开山之作。厄瓜多尔康涅狄格自然色茄衣，内裹尼加拉瓜烟叶。奶油、榛子、轻盈香料。尽管只是初次尝试，No.1 却从未退出目录——佩平一开始就想对了。","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"厄瓜多尔 Connecticut"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"向革命前的古巴烟厂致敬。康涅狄格宽叶马杜罗茄衣，包裹陈化的尼加拉瓜烟叶。黑巧克力、冷咖啡、糖蜜。比 Le Bijou 1922 更柔和，更平易，却同样出色。这是马杜罗爱好者进入 My Father 世界的入口。","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","story":"2010年——以儿子命名的系列，broadleaf 茄衣。","vitolas":[],"wrapper":"康涅狄格 broadleaf"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","story":"2012年——方压的尼加拉瓜纯料，家族农场日晒茄衣。","vitolas":[],"wrapper":"尼加拉瓜纯料"},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","story":"2012年——家族女儿詹妮·加西亚的品牌。","vitolas":[],"wrapper":"康涅狄格 broadleaf"},{"name":"El Centurión","color":"#7A2E1E","force":"Full","story":"2007年的限量版，2013年作为常规线回归。","vitolas":[],"wrapper":"尼加拉瓜 Habano"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","wrapper":"尼加拉瓜Habano","vitolas":[],"story":"2026年十月，零售商Cigarsdaily称其为My Father首个short filler自有品牌（简称S.F.），但2010年的一篇评论描述其茄芯为混合式，约70%为古巴种子的longfiller，取自Pepin García生产过程中的边角料。茄衣为尼加拉瓜Habano，茄套与茄芯均为尼加拉瓜所产，规格为Robusto 5 x 50，当时在售；2010年另有Corona 6 x 46。"}]',
  `gamme_ar` = '[{"name":"Le Bijou 1922","color":"#8B0000","force":"Full","story":"توربيدو (52 × 152 مم). خلطة نيكاراغوية معقّدة، وغلاف هابانو داكن من الإكوادور. أرز أحمر، ماكياتو، فلفل كبابة. إنه مرجع الدار — تُنتظر كل دفعة انتظار سنةٍ من الكروم.","vitolas":["Torpedo","Toro","Robusto","Petit Robusto","Churchill","Magnum"],"wrapper":"Habano Oscuro من الإكوادور"},{"name":"My Father No.1","color":"#722F37","force":"Medium-Full","story":"أُطلق عام 2008، وهو سيجار الدار الأول. غلاف كونيتيكت طبيعي من الإكوادور فوق تبغ نيكاراغوي. قشدة، بندق، توابل خفيفة. ورغم كونه محاولة أولى، لم يغادر الـNo.1 القائمة قط — فقد أصاب بيبين منذ البداية.","vitolas":["Toro","Robusto","Torpedo","Belicoso","Churchill","Juniors"],"wrapper":"Connecticut من الإكوادور"},{"name":"La Antiguedad","color":"#A0522D","force":"Medium-Full","story":"تحية إلى المصانع الكوبية لما قبل الثورة. غلاف كونيتيكت برودليف مادورو فوق تبغ نيكاراغوي معتَّق. شوكولاتة داكنة، قهوة باردة، دبس. أنعم من الـLe Bijou 1922، وأسهل تناولًا، ولا يقلّ تميّزًا. إنه مدخل عشّاق المادورو إلى عالم My Father.","vitolas":["Robusto","Toro","Torpedo","Churchill"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Jaime García Reserva Especial","color":"#4A3728","force":"Medium-Full","story":"2010 — الخطّ باسم الابن، غلاف برودليف.","vitolas":[],"wrapper":"برودليف كونيتيكت"},{"name":"Flor de las Antillas","color":"#8B5A2B","force":"Medium","story":"2012 — سيجار نيكاراغوي خالص مضغوط، غلاف مزروع تحت الشمس من مزارع العائلة.","vitolas":[],"wrapper":"نيكاراغوي خالص"},{"name":"La Dueña","color":"#8B1A6B","force":"Medium-Full","story":"2012 — علامة جاني غارسيا، ابنة الدار.","vitolas":[],"wrapper":"برودليف كونيتيكت"},{"name":"El Centurión","color":"#7A2E1E","force":"Full","story":"إصدار محدود من 2007، عاد خطًّا منتظمًا سنة 2013.","vitolas":[],"wrapper":"هابانو نيكاراغوي"},{"name":"Tabacos Baez","color":"#8B5A2B","force":"Medium","wrapper":"Habano من نيكاراغوا","vitolas":[],"story":"في أكتوبر 2026 يصفها تاجر التجزئة Cigarsdaily بأنها أول علامة خاصة لدى My Father من نوع short filler، ويُرمز إليه بـ S.F.، غير أن مراجعة تعود إلى 2010 تصف حشوة مختلطة، نحو 70% منها longfiller من بذور كوبية، مصنوعة من بقايا إنتاج Pepin García. غلاف خارجي Habano من نيكاراغوا فوق رابط وحشوة نيكاراغويين، بمقاس Robusto 5 x 50 المعروض للبيع في ذلك التاريخ، وبمقاس Corona 6 x 46 في 2010."}]',
  `mentions` = '["Old Henry Cigars"]',
  `source` = IF(LOCATE('holts.com « Old Henry » (octobre 2026 : nom d''un chien, viei', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'holts.com « Old Henry » (octobre 2026 : nom d''un chien, vieil ami de la maison ; cigares assemblés à Estelí par José Pepin Garcia et Jaime Garcia ; cape Habano d''Équateur, longfillers nicaraguayens, force Full ; six formats de Robusto 5,5 x 50 à Grandsire 6,5 x 64 ; classique depuis vingt ans) ; stogiereview.com « Old Henry » (18 avril 2007 : blend de Don Pepin produit pour Holt''s, vendu seulement chez Holt''s) ; cigarsdaily.com « My Father Tabacos Baez Robusto » (octobre 2026 : première marque short filler créée par My Father Cigars comme marque maison, Nicaragua, cape Habano, liant et tripe du Nicaragua, Robusto 5 x 50, en vente) ; stogiereview.com « Tabacos Baez Serie SF Corona » (5 mai 2010 : cigare attribué à Don Pepin Garcia, remplissage mixte d''environ 70 % de long filler de graine cubaine, chutes de la production, cape Habano du Nicaragua, liant nicaraguayen, Corona 6 x 46)')),
  `updated_at` = NOW()
 WHERE `name` = 'My Father';

-- ── Oliva — paragraphe : Rustico, Rustico Habano ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Oliva roule aussi, pour une seule ligne, Rustico, que le dét', `history`) > 0, `history`, CONCAT(`history`, '

', 'Oliva roule aussi, pour une seule ligne, Rustico, que le détaillant Atlantic Cigar Company, lancé à la fin des années 1990, vend sous le nom Rustico Habano. En octobre 2026, seule la ligne Reserve y est donnée comme faite par Oliva, au Nicaragua : cape Habano d''Équateur, liant et tripe nicaraguayens, longfiller roulé à la main, en Gordo 4 x 60. La ligne Habano y est donnée comme dominicaine, sans fabrique nommée.')),
  `history_en` = IF(LOCATE('Oliva also rolls Rustico, for a single line, which the retai', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Oliva also rolls Rustico, for a single line, which the retailer Atlantic Cigar Company, launched in the late 1990s, sells under the name Rustico Habano. In October 2026, only the Reserve line is given there as made by Oliva, in Nicaragua: Ecuadorian Habano wrapper, Nicaraguan binder and filler, hand-rolled longfiller, in Gordo 4 x 60. The Habano line is given there as Dominican, with no factory named.')),
  `history_es` = IF(LOCATE('Oliva también enrolla, para una sola línea, Rustico, que el ', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Oliva también enrolla, para una sola línea, Rustico, que el minorista Atlantic Cigar Company, lanzado a finales de la década de 1990, vende con el nombre Rustico Habano. En octubre de 2026, solo la línea Reserve figura allí como hecha por Oliva, en Nicaragua: capa Habano de Ecuador, capote y tripa nicaragüenses, longfiller enrollado a mano, en Gordo 4 x 60. La línea Habano figura allí como dominicana, sin fábrica nombrada.')),
  `history_de` = IF(LOCATE('Oliva rollt auch Rustico, für eine einzige Linie, die der Ei', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Oliva rollt auch Rustico, für eine einzige Linie, die der Einzelhändler Atlantic Cigar Company, Ende der 1990er Jahre gestartet, unter dem Namen Rustico Habano verkauft. Im Oktober 2026 wird dort nur die Linie Reserve als von Oliva in Nicaragua gefertigt angegeben: Habano-Deckblatt aus Ecuador, nicaraguanisches Umblatt und nicaraguanische Einlage, von Hand gerollter longfiller, im Gordo 4 x 60. Die Linie Habano wird dort als dominikanisch angegeben, ohne genannte Fabrik.')),
  `history_zh` = IF(LOCATE('Oliva还卷制Rustico，但仅限一条产品线；零售商Atlantic Cigar Company创办于1990年代末', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'Oliva还卷制Rustico，但仅限一条产品线；零售商Atlantic Cigar Company创办于1990年代末，以Rustico Habano之名销售该品牌。2026年十月，该零售商的页面仅将Reserve产品线列为Oliva在尼加拉瓜制造：茄衣为厄瓜多尔Habano，茄套与茄芯均为尼加拉瓜所产，手工卷制的longfiller，规格为Gordo 4 x 60。该页面将Habano产品线列为多米尼加所产，未点明工厂。')),
  `history_ar` = IF(LOCATE('تلفّ Oliva أيضًا، لخط واحد فقط، Rustico، التي يبيعها تاجر ال', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'تلفّ Oliva أيضًا، لخط واحد فقط، Rustico، التي يبيعها تاجر التجزئة Atlantic Cigar Company، الذي انطلق في أواخر عقد 1990، باسم Rustico Habano. وفي أكتوبر 2026 لا يُذكر هناك سوى خط Reserve على أنه من صنع Oliva في نيكاراغوا: غلاف خارجي Habano من الإكوادور، ورابط وحشوة نيكاراغويين، longfiller مُلَفّ يدويًا، بمقاس Gordo 4 x 60. ويُذكر خط Habano هناك على أنه دومينيكاني، دون ذكر اسم المصنع.')),
  `mentions` = '["Black Swan","Rustico","Rustico Habano"]',
  `source` = IF(LOCATE('atlanticcigar.com « Rustico Habano Reserve by Oliva Gordo (4', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'atlanticcigar.com « Rustico Habano Reserve by Oliva Gordo (4x60) 5-Pack » (octobre 2026 : ligne Reserve par Oliva, Nicaragua, cape Habano d''Équateur, liant et tripe nicaraguayens, roulé à la main en longfiller, Gordo 4 x 60, en stock) ; atlanticcigar.com « Rustico Habano Robusto » (octobre 2026 : marque Rustico Habano, Robusto 5 x 54, République dominicaine, cape Habano équatorienne de graine cubaine, aucune fabrique nommée, en stock) ; atlanticcigar.com « Rustico Habano » (octobre 2026 : cigares faits en République dominicaine, Habano Toro, Robusto et Gordo en vente) ; atlanticcigar.com « About Atlantic Cigar » (octobre 2026 : Atlantic Cigar Company LLC, entreprise familiale de vente au détail lancée à la fin des années 1990)')),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva';

-- ── Oscar Valladares — gamme : Island Jim ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Leaf by Oscar","color":"#6B4226","force":"Medium","story":"Le cigare enveloppé dans une feuille de tabac entière, à retirer avant d''allumer. C''est ce qui a fait connaître la maison, et ce qui la rend reconnaissable de loin.","vitolas":["Robusto","Toro","Sixty"],"wrapper":"Corojo, Connecticut, Maduro ou Sumatra selon les versions"},{"name":"Oscar Valladares 2012","color":"#8B5A2B","force":"Medium-Full","story":"L''année de fondation en guise de nom. La gamme classique de la maison, sans l''enveloppe de feuille — celle par laquelle on juge le tabac plutôt que l''idée.","vitolas":["Robusto","Toro"],"wrapper":"Assemblage hondurien"},{"name":"Super Fly","color":"#3A2A20","force":"Full","story":"Le versant corsé, en séries courtes. La maison travaille beaucoup en collaboration avec des détaillants, et ce registre s''y prête.","vitolas":["Robusto","Toro"],"wrapper":"Assemblage hondurien"},{"name":"Island Jim","color":"#4A3728","force":"Medium","wrapper":"San Andrés de Jalapa","vitolas":[],"story":"Ligne qui porte le nom de Jim Robinson, détaillant de Pittsburgh, présentée à l''IPCPR 2014 en format No. 2 au pied effiloché ; en mai 2025, ses cigares font partie du portefeuille de la maison. En octobre 2026, un détaillant en ligne décrit une cape San Andrés de Jalapa avec bande Connecticut et pointe Oscuro sur des longfillers nicaraguayens, de force moyenne ; le Barber Pole de 2025, en 6 x 52, entrecroise des capes Connecticut et Corojo."}]',
  `gamme_en` = '[{"name":"Leaf by Oscar","color":"#6B4226","force":"Medium","story":"The cigar wrapped in a whole tobacco leaf, to be removed before lighting. It is what made the house known, and what makes it recognisable from across a room.","vitolas":["Robusto","Toro","Sixty"],"wrapper":"Corojo, Connecticut, Maduro or Sumatra depending on the version"},{"name":"Oscar Valladares 2012","color":"#8B5A2B","force":"Medium-Full","story":"The founding year for a name. The house''s classic range, without the leaf sleeve — the one by which the tobacco is judged rather than the idea.","vitolas":["Robusto","Toro"],"wrapper":"Honduran blend"},{"name":"Super Fly","color":"#3A2A20","force":"Full","story":"The fuller side, in short runs. The house works a great deal with retailers, and this register suits that.","vitolas":["Robusto","Toro"],"wrapper":"Honduran blend"},{"name":"Island Jim","color":"#4A3728","force":"Medium","wrapper":"San Andrés from Jalapa","vitolas":[],"story":"Line named after Jim Robinson, a Pittsburgh retailer, presented at IPCPR 2014 in a No. 2 size with a frayed foot; in May 2025, its cigars are part of the company''s portfolio. In October 2026, an online retailer describes a San Andrés de Jalapa wrapper with a Connecticut band and an Oscuro tip over Nicaraguan longfillers, of medium strength; the 2025 Barber Pole, in 6 x 52, interlaces Connecticut and Corojo wrappers."}]',
  `gamme_es` = '[{"name":"Leaf by Oscar","color":"#6B4226","force":"Medium","story":"El puro envuelto en una hoja de tabaco entera, que se retira antes de encender. Es lo que dio a conocer a la casa, y lo que la hace reconocible de lejos.","vitolas":["Robusto","Toro","Sixty"],"wrapper":"Corojo, Connecticut, Maduro o Sumatra según las versiones"},{"name":"Oscar Valladares 2012","color":"#8B5A2B","force":"Medium-Full","story":"El año de fundación como nombre. La gama clásica de la casa, sin la funda de hoja: aquella por la que se juzga el tabaco y no la idea.","vitolas":["Robusto","Toro"],"wrapper":"Ligada hondureña"},{"name":"Super Fly","color":"#3A2A20","force":"Full","story":"La vertiente fuerte, en series cortas. La casa trabaja mucho en colaboración con detallistas, y este registro se presta a ello.","vitolas":["Robusto","Toro"],"wrapper":"Ligada hondureña"},{"name":"Island Jim","color":"#4A3728","force":"Medium","wrapper":"San Andrés de Jalapa","vitolas":[],"story":"Línea que lleva el nombre de Jim Robinson, minorista de Pittsburgh, presentada en el IPCPR 2014 en formato No. 2 con pie deshilachado; en mayo de 2025, sus puros forman parte del portafolio de la casa. En octubre de 2026, un minorista en línea describe una capa San Andrés de Jalapa con banda Connecticut y punta Oscuro sobre longfillers nicaragüenses, de fuerza medium; el Barber Pole de 2025, en 6 x 52, entrecruza capas Connecticut y Corojo."}]',
  `gamme_de` = '[{"name":"Leaf by Oscar","color":"#6B4226","force":"Medium","story":"Die Zigarre, in ein ganzes Tabakblatt gewickelt, das vor dem Anzünden abgenommen wird. Sie hat das Haus bekannt gemacht und macht es von weitem erkennbar.","vitolas":["Robusto","Toro","Sixty"],"wrapper":"Corojo, Connecticut, Maduro oder Sumatra je nach Fassung"},{"name":"Oscar Valladares 2012","color":"#8B5A2B","force":"Medium-Full","story":"Das Gründungsjahr als Name. Die klassische Linie des Hauses, ohne Blatthülle — jene, an der man den Tabak beurteilt und nicht die Idee.","vitolas":["Robusto","Toro"],"wrapper":"Honduranische Mischung"},{"name":"Super Fly","color":"#3A2A20","force":"Full","story":"Die kräftige Seite, in kurzen Serien. Das Haus arbeitet viel mit Händlern zusammen, und dieses Register eignet sich dafür.","vitolas":["Robusto","Toro"],"wrapper":"Honduranische Mischung"},{"name":"Island Jim","color":"#4A3728","force":"Medium","wrapper":"San Andrés aus Jalapa","vitolas":[],"story":"Linie, die den Namen von Jim Robinson trägt, einem Einzelhändler aus Pittsburgh, auf der IPCPR 2014 im Format No. 2 mit ausgefranstem Fuß vorgestellt; im Mai 2025 gehören ihre Zigarren zum Portfolio des Hauses. Im Oktober 2026 beschreibt ein Online-Einzelhändler ein Deckblatt San Andrés de Jalapa mit Connecticut-Band und Oscuro-Spitze über nicaraguanischen longfillers, von Stärke medium; der Barber Pole von 2025, im Format 6 x 52, verflechtet Deckblätter Connecticut und Corojo."}]',
  `gamme_zh` = '[{"name":"Leaf by Oscar","color":"#6B4226","force":"Medium","story":"外裹一整片烟叶的雪茄，点燃前取下。正是它让这家为人所知，也让它远远就能被认出。","vitolas":["Robusto","Toro","Sixty"],"wrapper":"依版本而定：Corojo、康涅狄格、马杜罗或苏门答腊"},{"name":"Oscar Valladares 2012","color":"#8B5A2B","force":"Medium-Full","story":"以创立之年为名。这家的经典系列，没有那层叶套——评判的是烟草本身，而非那个点子。","vitolas":["Robusto","Toro"],"wrapper":"洪都拉斯配方"},{"name":"Super Fly","color":"#3A2A20","force":"Full","story":"浓烈的一侧，小批量生产。这家常与零售商合作，而这种风格正适合此道。","vitolas":["Robusto","Toro"],"wrapper":"洪都拉斯配方"},{"name":"Island Jim","color":"#4A3728","force":"Medium","wrapper":"Jalapa的San Andrés","vitolas":[],"story":"该产品线以Pittsburgh零售商Jim Robinson的名字命名，于IPCPR 2014上亮相，规格为脚部呈散丝状的No. 2；2025年五月，其雪茄已属该公司的产品组合。2026年十月，一家在线零售商描述其茄衣为San Andrés de Jalapa，带有Connecticut条带和Oscuro尖端，配尼加拉瓜longfillers，烟力为medium；2025年的Barber Pole规格为6 x 52，由Connecticut和Corojo茄衣交织而成。"}]',
  `gamme_ar` = '[{"name":"Leaf by Oscar","color":"#6B4226","force":"Medium","story":"السيجار الملفوف بورقة تبغ كاملة تُنزَع قبل الإشعال. هو ما عرّف بالدار، وما يجعلها تُعرَف من بعيد.","vitolas":["Robusto","Toro","Sixty"],"wrapper":"كوروخو أو كونيتيكت أو مادورو أو سومطرة بحسب النسخة"},{"name":"Oscar Valladares 2012","color":"#8B5A2B","force":"Medium-Full","story":"سنة التأسيس اسمًا. السلسلة الكلاسيكية للدار، بلا غلاف الورقة — تلك التي يُحكَم بها على التبغ لا على الفكرة.","vitolas":["Robusto","Toro"],"wrapper":"مزيج هندوراسي"},{"name":"Super Fly","color":"#3A2A20","force":"Full","story":"الوجه القويّ، بدفعات قصيرة. تعمل الدار كثيرًا بالشراكة مع بائعي التجزئة، وهذا المزاج يلائم ذلك.","vitolas":["Robusto","Toro"],"wrapper":"مزيج هندوراسي"},{"name":"Island Jim","color":"#4A3728","force":"Medium","wrapper":"San Andrés من Jalapa","vitolas":[],"story":"خط يحمل اسم Jim Robinson، تاجر التجزئة في Pittsburgh، قُدّم في IPCPR 2014 بمقاس No. 2 بقدم مهدّبة؛ وفي مايو 2025 تدخل سيجاراته ضمن محفظة الشركة. وفي أكتوبر 2026 يصف تاجر تجزئة عبر الإنترنت غلافًا خارجيًا San Andrés de Jalapa بشريط Connecticut وطرف Oscuro فوق longfillers نيكاراغويين، بقوة medium؛ أما Barber Pole لعام 2025، بمقاس 6 x 52، فيتشابك فيه غلافان خارجيان Connecticut وCorojo."}]',
  `source` = IF(LOCATE('cigar-coop.com « Cigar News: Island Jim by Oscar » (22 août ', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « Cigar News: Island Jim by Oscar » (22 août 2014 : Island Jim nommé d''après Jim Robinson, détaillant de Pittsburgh, présenté à l''IPCPR 2014 par Oscar Valladares Tobacco and Company ; pied effiloché, format dit No. 2) ; cigar-coop.com « PCA 2025: Oscar Valladares Tobacco Co. » (30 mai 2025 : Island Jim Barber Pole, quatrième cigare de la ligne, 6 x 52, capes Connecticut et Corojo, boîtes de 21 ; les lignes de Robinson font partie du portefeuille de la maison) ; cigarsdirect.com « Oscar Valladares Island Jim » (octobre 2026 : Island Jim #2, cape San Andrés de Jalapa avec bande Connecticut et pointe Oscuro, liant et longfillers nicaraguayens, force moyenne, en Barber Pole, Connecticut, Maduro et Natural ; Island Jim propriétaire du magasin Leaf & Bean à Pittsburgh)')),
  `updated_at` = NOW()
 WHERE `name` = 'Oscar Valladares';

-- ── Ozgener Family Cigars — paragraphe : Oz Family ──
UPDATE `brands` SET
  `history` = IF(LOCATE('La maison s''écrit aussi Oz Family Cigars. Lancée en 2022 sou', `history`) > 0, `history`, CONCAT(`history`, '

', 'La maison s''écrit aussi Oz Family Cigars. Lancée en 2022 sous le nom d''Ozgener Family Cigars, elle l''a raccourci : un compte rendu du salon PCA d''avril 2024 écrit que le choix a été fait de dire Oz Family Cigars, et en mars 2026 ses deux éditions annoncées, Maracana et World Cup 2026, portent ce nom. En octobre 2026, smokingpipes.com range ses cigares sous le nom OZ Family. Crowned Heads, dont Tim Ozgener est devenu investisseur en 2022, les distribue — en mars 2026 encore.')),
  `history_en` = IF(LOCATE('The company is also written Oz Family Cigars. Launched in 20', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'The company is also written Oz Family Cigars. Launched in 2022 under the name Ozgener Family Cigars, it has shortened it: a report on the PCA show of April 2024 writes that the choice was made to say Oz Family Cigars, and in March 2026 its two announced editions, Maracana and World Cup 2026, bear that name. In October 2026, smokingpipes.com lists its cigars under the name OZ Family. Crowned Heads, in which Tim Ozgener became an investor in 2022, distributes them — still in March 2026.')),
  `history_es` = IF(LOCATE('La casa se escribe también Oz Family Cigars. Lanzada en 2022', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'La casa se escribe también Oz Family Cigars. Lanzada en 2022 con el nombre de Ozgener Family Cigars, lo ha acortado: una crónica del salón PCA de abril de 2024 escribe que se tomó la decisión de decir Oz Family Cigars, y en marzo de 2026 sus dos ediciones anunciadas, Maracana y World Cup 2026, llevan ese nombre. En octubre de 2026, smokingpipes.com clasifica sus puros bajo el nombre OZ Family. Crowned Heads, en la que Tim Ozgener se convirtió en inversor en 2022, los distribuye, todavía en marzo de 2026.')),
  `history_de` = IF(LOCATE('Das Haus schreibt sich auch Oz Family Cigars. 2022 unter dem', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Das Haus schreibt sich auch Oz Family Cigars. 2022 unter dem Namen Ozgener Family Cigars gestartet, hat es ihn gekürzt: Ein Bericht über die PCA-Messe vom April 2024 schreibt, man habe entschieden, Oz Family Cigars zu sagen, und im März 2026 tragen seine beiden angekündigten Editionen, Maracana und World Cup 2026, diesen Namen. Im Oktober 2026 ordnet smokingpipes.com seine Zigarren unter dem Namen OZ Family ein. Crowned Heads, deren Investor Tim Ozgener 2022 geworden ist, vertreibt sie – im März 2026 weiterhin.')),
  `history_zh` = IF(LOCATE('这家公司也写作Oz Family Cigars。其于2022年以Ozgener Family Cigars之名推出，后来', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '这家公司也写作Oz Family Cigars。其于2022年以Ozgener Family Cigars之名推出，后来将其缩短：PCA展会2024年四月的一篇报道写道，已作出称作Oz Family Cigars的选择，2026年三月其两款已宣布的版本Maracana和World Cup 2026也采用这一名称。2026年十月，smokingpipes.com将其雪茄归在OZ Family名下。Crowned Heads负责分销这些雪茄（Tim Ozgener于2022年成为其投资人），2026年三月时仍是如此。')),
  `history_ar` = IF(LOCATE('تُكتب الشركة أيضًا Oz Family Cigars. أُطلقت في 2022 باسم Ozg', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'تُكتب الشركة أيضًا Oz Family Cigars. أُطلقت في 2022 باسم Ozgener Family Cigars ثم اختصرته: يكتب تقرير عن معرض PCA في أبريل 2024 أن الاختيار وقع على قول Oz Family Cigars، وفي مارس 2026 يحمل إصداراها المعلنان، Maracana وWorld Cup 2026، هذا الاسم. وفي أكتوبر 2026 يُدرج smokingpipes.com سيجاراتها تحت اسم OZ Family. وتوزّعها Crowned Heads، التي أصبح Tim Ozgener مستثمرًا فيها في 2022، وما زالت تفعل ذلك في مارس 2026.')),
  `mentions` = '["Oz Family"]',
  `source` = IF(LOCATE('cigar-coop.com « PCA 2024: Oz Family Cigars » (3 avril 2024 ', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « PCA 2024: Oz Family Cigars » (3 avril 2024 : lancée sous le nom d''Ozgener Family Cigars, le choix a été fait de le raccourcir en Oz Family Cigars) ; cigaraficionado.com « Two Soccer-Themed Smokes From Oz Family Cigars » (20 mars 2026 : Maracana et World Cup 2026 paraissent sous le nom OZ Family Cigars, distribués par Crowned Heads) ; cigar-coop.com « Cigar News: Tim Ozgener Returning to Cigar Industry » (juin 2022 : Ozgener Family Cigars, lancée en 2022, distribuée par Crowned Heads ; Tim Ozgener devient investisseur de Crowned Heads) ; smokingpipes.com « Cigars / OZ Family » (7 octobre 2026 : la rubrique s''intitule OZ Family, son texte d''histoire dit Ozgener Family Cigars)')),
  `updated_at` = NOW()
 WHERE `name` = 'Ozgener Family Cigars';

-- ── Plasencia — paragraphe : Astoria de Nicaragua ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Selon cigarworld.de, Plasencia roule aussi Astoria de Nicara', `history`) > 0, `history`, CONCAT(`history`, '

', 'Selon cigarworld.de, Plasencia roule aussi Astoria de Nicaragua, une marque vendue en Allemagne. En octobre 2026, le détaillant la propose avec Tabac Benden GmbH (Düsseldorf) pour importateur et Tabacalera Plasencia, à Estelí, pour fabricant : roulée à la main, en tripe mediumfiller, tout en tabac nicaraguayen. Il l''a à son catalogue depuis le 1er octobre 2010 pour la Classic, depuis le 23 avril 2025 pour la série Crimez (Hate, Kidnapping, Manslaughter), et l''importe en direct depuis 2024, son ancien importateur ayant cessé son activité.')),
  `history_en` = IF(LOCATE('According to cigarworld.de, Plasencia also rolls Astoria de ', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'According to cigarworld.de, Plasencia also rolls Astoria de Nicaragua, a brand sold in Germany. In October 2026, the retailer offers it with Tabac Benden GmbH (Düsseldorf) as importer and Tabacalera Plasencia, in Estelí, as manufacturer: hand-rolled, with a mediumfiller filler, made entirely of Nicaraguan tobacco. It has had it in its catalogue since 1 October 2010 for the Classic, since 23 April 2025 for the Crimez series (Hate, Kidnapping, Manslaughter), and has imported it directly since 2024, its former importer having ceased trading.')),
  `history_es` = IF(LOCATE('Según cigarworld.de, Plasencia enrolla también Astoria de Ni', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Según cigarworld.de, Plasencia enrolla también Astoria de Nicaragua, una marca vendida en Alemania. En octubre de 2026, el minorista la ofrece con Tabac Benden GmbH (Düsseldorf) como importador y Tabacalera Plasencia, en Estelí, como fabricante: enrollada a mano, con tripa mediumfiller, toda ella de tabaco nicaragüense. La tiene en su catálogo desde el 1 de octubre de 2010 para la Classic, desde el 23 de abril de 2025 para la serie Crimez (Hate, Kidnapping, Manslaughter), y la importa directamente desde 2024, habiendo cesado su actividad su anterior importador.')),
  `history_de` = IF(LOCATE('Laut cigarworld.de rollt Plasencia auch Astoria de Nicaragua', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Laut cigarworld.de rollt Plasencia auch Astoria de Nicaragua, eine in Deutschland verkaufte Marke. Im Oktober 2026 bietet der Einzelhändler sie mit Tabac Benden GmbH (Düsseldorf) als Importeur und Tabacalera Plasencia in Estelí als Hersteller an: von Hand gerollt, mit Einlage mediumfiller, ganz aus nicaraguanischem Tabak. Er führt sie seit dem 1. Oktober 2010 für die Classic, seit dem 23. April 2025 für die Serie Crimez (Hate, Kidnapping, Manslaughter) in seinem Katalog und importiert sie seit 2024 direkt, da sein früherer Importeur den Betrieb eingestellt hat.')),
  `history_zh` = IF(LOCATE('据cigarworld.de，Plasencia也卷制Astoria de Nicaragua，这是一个在德国销售的品牌', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '据cigarworld.de，Plasencia也卷制Astoria de Nicaragua，这是一个在德国销售的品牌。2026年十月，该零售商供应这一品牌，进口商为Tabac Benden GmbH（Düsseldorf），制造商为位于Estelí的Tabacalera Plasencia：手工卷制，茄芯为mediumfiller，全部采用尼加拉瓜烟叶。该零售商将Classic列入目录，始于2010年十月1日，将Crimez系列（Hate、Kidnapping、Manslaughter）列入目录，始于2025年四月23日，并自2024年起直接进口，其原进口商已停止营业。')),
  `history_ar` = IF(LOCATE('بحسب cigarworld.de، تلفّ Plasencia أيضًا Astoria de Nicaragu', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'بحسب cigarworld.de، تلفّ Plasencia أيضًا Astoria de Nicaragua، وهي علامة تُباع في ألمانيا. وفي أكتوبر 2026 يعرضها تاجر التجزئة مع Tabac Benden GmbH (Düsseldorf) مستوردًا وTabacalera Plasencia في Estelí مصنّعًا: ملفوفة يدويًا، بحشوة mediumfiller، كلها من تبغ نيكاراغوي. وهو يدرجها في فهرسه منذ 1 أكتوبر 2010 بالنسبة إلى Classic، ومنذ 23 أبريل 2025 بالنسبة إلى سلسلة Crimez (Hate وKidnapping وManslaughter)، ويستوردها مباشرة منذ 2024، بعد أن توقف مستورده السابق عن نشاطه.')),
  `mentions` = '["Astoria de Nicaragua"]',
  `source` = IF(LOCATE('cigarworld.de « Astoria de Nicaragua » (7 octobre 2026 : rou', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigarworld.de « Astoria de Nicaragua » (7 octobre 2026 : roulée à la main chez Tabacalera Plasencia à Estelí, importée en direct depuis 2024 après l''arrêt de l''ancien importateur ; séries Classic et Crimez) ; cigarworld.de « Astoria de Nicaragua Classic Robustos » (7 octobre 2026 : Tabac Benden GmbH, Düsseldorf, portée comme importateur ; fabricant Plasencia S.A. ; tabac nicaraguayen ; au catalogue depuis le 1er octobre 2010) ; cigarworld.de « Astoria de Nicaragua Crimez Hate » (7 octobre 2026 : au catalogue depuis le 23 avril 2025 ; Tabac Benden GmbH portée comme importateur ; fabricant Plasencia S.A. ; roulage à la main, tripe mediumfiller) ; cigarworld.de « Astoria de Nicaragua Crimez » (7 octobre 2026 : série Crimez en trois variantes, Hate, Kidnapping, Manslaughter ; importation directe depuis 2024)')),
  `updated_at` = NOW()
 WHERE `name` = 'Plasencia';

-- ── Rocky Patel — gamme : Bold by Nish Patel ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"Le nom renvoie à l''origine des capes du premier assemblage, récoltées en 1992 — pas à l''âge du tabac vendu aujourd''hui. Cape Ecuador Connecticut sur tabacs honduriens et nicaraguayens. Notes de noisette grillée, caramel, bois clair. Mi-corsée à corsée, équilibrée ; la série Vintage reste l''une des propositions les plus narratives du marché : chaque millésime raconte une récolte.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Lancée pour les 50 ans de Rocky Patel — l''homme, pas la marque. Assemblage hondurien-nicaraguayen complexe, cape d''Équateur cultivée en plein soleil. Notes de café, épices orientales, sous-bois. Format Toro, 50 x 152mm. Une gamme qui reste dans l''ombre des séries Vintage alors qu''elle en dit autant sur la maison.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Plein soleil d''Équateur"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"La gamme accessible de la maison. Formats Robusto et Toro, cape Connecticut, tabacs hondurien et nicaraguayen. Notes douces de crème et de noisette. Le premier Rocky Patel pour un néophyte — facile d''approche, régulier, gratifiant. Prix démocratique.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"Les cigares d''Hamlet Paredes, ancien rouleur de Partagás et ambassadeur d''Habanos, engagé en 2015 — Tabaquero d''abord, puis Liberation et 25th Year. Paredes est parti en août 2022 ; la maison garde le nom et les lignes, et a arrêté Tabaquero.","vitolas":[],"wrapper":"San Andrés (Mexique)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"La première marque de Rocky Patel, dans les années 1990, avant que la maison ne prenne son nom. Le recensement de cet atlas la prenait pour une maison hondurienne à part.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","wrapper":"Connecticut Broadleaf Maduro","vitolas":[],"story":"Lancée en 2013 par Nish Patel, frère de Rocky Patel et vice-président exécutif de la maison, à la suite de sa première sortie de 2011 ; en mars 2024, un article de la Premium Cigar Association le dit à la tête de la ligne, produite au Nicaragua. Tabacs de San Andrés et des fermes nicaraguayennes de la maison sous la cape, en Robusto (5 ½ x 50), Toro (6 x 52), Torpedo (6 ⅛ x 52) et Sixty (6 x 60), dit rockypatel.com."}]',
  `gamme_en` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"The name refers to the origin of the wrappers used in the first blend, harvested in 1992 — not to the age of the tobacco sold today. Ecuador Connecticut wrapper over Honduran and Nicaraguan leaf. Toasted hazelnut, caramel, pale wood. A balanced medium-full, and the Vintage series remains one of the most narrative propositions on the market: each vintage tells of a harvest.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Launched for Rocky Patel''s fiftieth birthday — the man, not the brand. A complex Honduran-Nicaraguan blend, Ecuadorian wrapper grown in full sun. Coffee, oriental spice, forest floor. Toro format, 50 x 152mm. A range that stays in the shadow of the Vintage series though it says just as much about the house.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Ecuadorian Sun-Grown"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"The house''s accessible range. Robusto and Toro formats, Connecticut wrapper, Honduran and Nicaraguan leaf. Gentle cream and hazelnut. The first Rocky Patel for a newcomer — easy to approach, consistent, rewarding. A democratic price.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"The cigars of Hamlet Paredes, former Partagás roller and Habanos ambassador, hired in 2015 — Tabaquero first, then Liberation and 25th Year. Paredes left in August 2022; the house keeps the name and the lines, and discontinued Tabaquero.","vitolas":[],"wrapper":"San Andrés (Mexico)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"Rocky Patel''s first brand, in the 1990s, before the house took his name. This atlas''s census took it for a separate Honduran house.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","wrapper":"Connecticut Broadleaf Maduro","vitolas":[],"story":"Launched in 2013 by Nish Patel, brother of Rocky Patel and executive vice president of the company, following his first release in 2011; in March 2024, an article by the Premium Cigar Association says he heads the line, which is produced in Nicaragua. Tobaccos from San Andrés and from the company''s Nicaraguan farms under the wrapper, in Robusto (5½ x 50), Toro (6 x 52), Torpedo (6⅛ x 52) and Sixty (6 x 60), according to rockypatel.com."}]',
  `gamme_es` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"El nombre remite al origen de las capas del primer ligado, cosechadas en 1992, no a la edad del tabaco que se vende hoy. Capa Ecuador Connecticut sobre tabacos hondureños y nicaragüenses. Avellana tostada, caramelo, madera clara. Un medio-fuerte equilibrado, y la serie Vintage sigue siendo una de las propuestas más narrativas del mercado: cada añada cuenta una cosecha.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Lanzada por los 50 años de Rocky Patel, el hombre, no la marca. Ligado hondureño-nicaragüense complejo, capa ecuatoriana cultivada a pleno sol. Café, especias orientales, sotobosque. Formato Toro, 50 x 152mm. Una gama que permanece a la sombra de las series Vintage aunque diga otro tanto sobre la casa.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"De sol de Ecuador"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"La gama accesible de la casa. Formatos Robusto y Toro, capa Connecticut, tabacos hondureño y nicaragüense. Notas suaves de crema y avellana. El primer Rocky Patel para un neófito: fácil de abordar, regular, gratificante. Precio democrático.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"Los puros de Hamlet Paredes, antiguo torcedor de Partagás y embajador de Habanos, contratado en 2015 — Tabaquero primero, luego Liberation y 25th Year. Paredes se fue en agosto de 2022; la casa conserva el nombre y las líneas, y retiró Tabaquero.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"La primera marca de Rocky Patel, en los años 1990, antes de que la casa tomara su nombre. El censo de este atlas la tomaba por una casa hondureña aparte.","vitolas":[],"wrapper":"No divulgada"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","wrapper":"Connecticut Broadleaf Maduro","vitolas":[],"story":"Lanzada en 2013 por Nish Patel, hermano de Rocky Patel y vicepresidente ejecutivo de la casa, a raíz de su primer lanzamiento de 2011; en marzo de 2024, un artículo de la Premium Cigar Association afirma que está al frente de la línea, producida en Nicaragua. Tabacos de San Andrés y de las fincas nicaragüenses de la casa bajo la capa, en Robusto (5½ x 50), Toro (6 x 52), Torpedo (6⅛ x 52) y Sixty (6 x 60), según rockypatel.com."}]',
  `gamme_de` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"Der Name verweist auf die Herkunft der Deckblätter der ersten Mischung, geerntet 1992 — nicht auf das Alter des heute verkauften Tabaks. Deckblatt Ecuador Connecticut über honduranischem und nicaraguanischem Tabak. Geröstete Haselnuss, Karamell, helles Holz. Ein ausgewogenes Medium-Full, und die Vintage-Serie bleibt eines der erzählerischsten Angebote des Marktes: Jeder Jahrgang erzählt von einer Ernte.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Zum 50. Geburtstag von Rocky Patel lanciert — dem Mann, nicht der Marke. Komplexe honduranisch-nicaraguanische Mischung, ecuadorianisches Deckblatt aus vollem Sonnenanbau. Kaffee, orientalische Gewürze, Waldboden. Format Toro, 50 x 152 mm. Eine Serie, die im Schatten der Vintage-Reihen bleibt, obwohl sie ebenso viel über das Haus erzählt.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"Sonnenanbau aus Ecuador"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"Die zugängliche Serie des Hauses. Formate Robusto und Toro, Deckblatt Connecticut, honduranischer und nicaraguanischer Tabak. Milde Noten von Sahne und Haselnuss. Der erste Rocky Patel für Einsteiger — leicht zugänglich, gleichmäßig, dankbar. Ein demokratischer Preis.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"Die Zigarren von Hamlet Paredes, ehemaligem Partagás-Roller und Habanos-Botschafter, 2015 engagiert — zuerst Tabaquero, dann Liberation und 25th Year. Paredes ging im August 2022; das Haus behält Namen und Linien und stellte Tabaquero ein.","vitolas":[],"wrapper":"San Andrés (Mexiko)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"Rocky Patels erste Marke, in den 1990ern, bevor das Haus seinen Namen annahm. Die Zählung dieses Atlas hielt sie für ein eigenes honduranisches Haus.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","wrapper":"Connecticut Broadleaf Maduro","vitolas":[],"story":"2013 von Nish Patel, dem Bruder von Rocky Patel und Executive Vice President des Hauses, im Anschluss an seine erste Veröffentlichung von 2011 auf den Markt gebracht; im März 2024 nennt ihn ein Artikel der Premium Cigar Association an der Spitze der Linie, die in Nicaragua produziert wird. Tabake aus San Andrés und von den nicaraguanischen Farmen des Hauses unter dem Deckblatt, in Robusto (5½ x 50), Toro (6 x 52), Torpedo (6⅛ x 52) und Sixty (6 x 60), laut rockypatel.com."}]',
  `gamme_zh` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"名字指的是首款配方所用茄衣的来历——那批茄衣收于 1992 年，而不是今天所售烟叶的年份。厄瓜多尔康涅狄格茄衣，包裹洪都拉斯与尼加拉瓜烟叶。烤榛子、焦糖、浅色木。中偏浓而均衡；Vintage 系列至今仍是市场上最有叙事性的构想之一：每一个年份都在讲一次收成。","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"为洛基·帕特尔五十岁而推出——是这个人，不是这个牌子。复杂的洪都拉斯－尼加拉瓜配方，茄衣来自厄瓜多尔的全日照种植。咖啡、东方香料、林下腐叶。Toro 规格，50 x 152 毫米。这个系列一直被 Vintage 各系列的光芒盖住，可它讲出的老号故事并不更少。","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"厄瓜多尔日光种植"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"这家老号的入门系列。Robusto 与 Toro 两种规格，康涅狄格茄衣，洪都拉斯与尼加拉瓜烟叶。奶油与榛子的柔和气息。给新手的第一支洛基·帕特尔——好上手、稳定、有回报。价格亲民。","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"哈姆雷特·帕雷德斯的雪茄——他曾是 Partagás 的卷工与 Habanos 的大使，2015年受聘——先是 Tabaquero，再是 Liberation 与 25th Year。帕雷德斯2022年8月离开；公司保留名字与各线，停掉了 Tabaquero。","vitolas":[],"wrapper":"圣安德烈斯（墨西哥）"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"洛基·帕特尔的第一个品牌，1990年代，早于公司改用他的名字。本图集的普查曾把它当作另一家洪都拉斯公司。","vitolas":[],"wrapper":"未公开"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","wrapper":"Connecticut Broadleaf Maduro","vitolas":[],"story":"2013年由Nish Patel推出，他是Rocky Patel的兄弟、公司的执行副总裁，此前于2011年首次发售；2024年三月，Premium Cigar Association的一篇文章称他主持该产品线，该产品线在尼加拉瓜生产。茄衣之下为来自San Andrés和公司尼加拉瓜农场的烟叶，规格为Robusto（5½ x 50）、Toro（6 x 52）、Torpedo（6⅛ x 52）和Sixty（6 x 60），据rockypatel.com。"}]',
  `gamme_ar` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"يشير الاسم إلى أصل أغلفة الخلطة الأولى، وقد جُنيت عام 1992 — لا إلى عمر التبغ المُباع اليوم. غلاف إكوادور كونيتيكت فوق تبغ هندوراسي ونيكاراغوي. بندق محمّص، كراميل، خشب فاتح. قوّة متوسطة-عالية متوازنة، وتبقى سلسلة Vintage من أكثر الطروحات سرديّة في السوق: كل سنة تروي حصادًا.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"أُطلقت في عيد ميلاد روكي باتيل الخمسين — الرجل لا العلامة. خلطة هندوراسية-نيكاراغوية معقّدة، وغلاف إكوادوري مزروع في الشمس الكاملة. قهوة، توابل شرقية، أرض غابة. قياس تورو، 50 × 152 مم. مجموعة تبقى في ظلّ سلاسل Vintage، مع أنها تقول عن الدار قدر ما تقوله تلك.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"مزروع في الشمس من الإكوادور"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"المجموعة السهلة لدى الدار. قياسا روبوستو وتورو، غلاف كونيتيكت، وتبغ هندوراسي ونيكاراغوي. نفحات ناعمة من القشدة والبندق. أول روكي باتيل للمبتدئ — سهل التناول، ثابت، مُجزٍ. وسعره في متناول الجميع.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"سيجارات هاملت باريديس، لفّاف Partagás السابق وسفير Habanos، الذي استُقدم سنة 2015 — Tabaquero أوّلًا، ثم Liberation و25th Year. غادر باريديس في آب/أغسطس 2022؛ وتحتفظ الدار بالاسم والخطوط، وأوقفت Tabaquero.","vitolas":[],"wrapper":"سان أندريس (المكسيك)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"أوّل علامة لروكي باتيل، في التسعينيات، قبل أن تتّخذ الدار اسمه. وكان إحصاء هذا الأطلس يحسبها دارًا هندوراسية مستقلّة.","vitolas":[],"wrapper":"غير معلن"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","wrapper":"Connecticut Broadleaf Maduro","vitolas":[],"story":"أُطلق في 2013 على يد Nish Patel، شقيق Rocky Patel ونائب الرئيس التنفيذي في الشركة، في أعقاب إصداره الأول عام 2011؛ وفي مارس 2024 يذكر مقال لـ Premium Cigar Association أنه يتولى قيادة الخط، الذي يُنتَج في نيكاراغوا. تبغ من San Andrés ومن مزارع الشركة في نيكاراغوا تحت الغلاف الخارجي، بمقاسات Robusto (5½ x 50) وToro (6 x 52) وTorpedo (6⅛ x 52) وSixty (6 x 60)، بحسب rockypatel.com."}]',
  `source` = IF(LOCATE('rockypatel.com « Nish Patel » (page de la famille, non datée', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'rockypatel.com « Nish Patel » (page de la famille, non datée : frère cadet de Rocky Patel, arrivé en Floride en 2004 et vice-président exécutif ; première sortie en 2011, Bold by Nish Patel en 2013, cape maduro) ; rockypatel.com « Bold by Nish Patel » (pied de page 2025 : cape Connecticut Broadleaf Maduro, tabacs de San Andrés et des fermes de la maison au Nicaragua, cigare décrit comme corsé et riche, formats Robusto, Toro, Torpedo, Sixty) ; burnbyrockypatel.com « Bold by Nish Patel » (non daté : force Medium Plus) ; premiumcigars.org « Rocky Patel Premium Cigars: Always Innovating » (7 mars 2024 : Nish Patel dirige la ligne BOLD, produite au Nicaragua)')),
  `updated_at` = NOW()
 WHERE `name` = 'Rocky Patel';

-- ── Tabacalera Palma — gamme : Rough Rider, Cuban Aristocrat, La Instructora ──
UPDATE `brands` SET
  `gamme` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"La marque propre de la fabrique, et la seule qu''elle signe de son nom. Le mot désigne l''atelier de roulage lui-même — la salle où les torcedores travaillent en rangs.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Assemblages dominicains, capes variées"},{"name":"Rough Rider","color":"#C9A96E","force":null,"wrapper":"Connecticut, maduro, candela","vitolas":[],"story":"Marque de Jochy Blanco, venue du portefeuille d''IndianHead qu''il a racheté en 2015 à Bill Bock ; la ligne Rough Rider Sweets compte trois cigares, Connecticut, Maduro et Candela, ce dernier présenté au PCA 2025 en Robusto (5 x 50), Toro (6 x 52) et Gordo (6 x 60), tripe de Criollo 98, Piloto Cubano et Cameroun, roulé à Tabacalera Palma. Un article de la Premium Cigar Association d''avril 2024 la décrit en longfiller, à bout sucré."},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Connecticut, habano, maduro","vitolas":[],"story":"Parue en 2007 selon cigarcentury.com, qui la dit faite par Tabacalera Palma, avec liant dominicain et tripe du Nicaragua et de République dominicaine ; entrée en 2015 chez Jochy Blanco avec le rachat d''IndianHead. En avril 2024, un article de la Premium Cigar Association la range parmi les lignes à tripe mixte (mixed-fill) de la fabrique, vendue en boîtes."},{"name":"La Instructora","color":"#6B4226","force":"Medium","wrapper":"Cubra brésilien, Connecticut","vitolas":[],"story":"Projet commun de Jochy Blanco, qui en a assemblé la Delicado, et d''Aaron Saide, nommé son fondateur par luxurycigarclub.com ; sur le marché depuis 2017, roulée à Tabacalera Palma, avec la Box Pressed (cape Cubra du Brésil, liant Piloto, tripe de Criollo 98 et de Piloto dominicains) et la Delicado (cape Connecticut américain). En avril 2024, un article de la Premium Cigar Association la range parmi les marques haut de gamme de la fabrique."}]',
  `gamme_en` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"The factory''s own brand, and the only one it signs with its own name. The word names the rolling floor itself — the room where the torcedores work in rows.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Dominican blends, varied wrappers"},{"name":"Rough Rider","color":"#C9A96E","force":null,"wrapper":"Connecticut, maduro, candela","vitolas":[],"story":"A brand of Jochy Blanco, coming from the IndianHead portfolio that he bought in 2015 from Bill Bock; the Rough Rider Sweets line has three cigars, Connecticut, Maduro and Candela, the last shown at PCA 2025 in Robusto (5 x 50), Toro (6 x 52) and Gordo (6 x 60), with a filler of Criollo 98, Piloto Cubano and Cameroon, rolled at Tabacalera Palma. An article by the Premium Cigar Association of April 2024 describes it as longfiller, with a sweet tip."},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Connecticut, habano, maduro","vitolas":[],"story":"Released in 2007 according to cigarcentury.com, which says it is made by Tabacalera Palma, with a Dominican binder and a filler from Nicaragua and the Dominican Republic; it came to Jochy Blanco in 2015 with the purchase of IndianHead. In April 2024, an article by the Premium Cigar Association places it among the factory''s mixed-filler lines (mixed-fill), sold in boxes."},{"name":"La Instructora","color":"#6B4226","force":"Medium","wrapper":"Brazilian Cubra, Connecticut","vitolas":[],"story":"A joint project of Jochy Blanco, who blended the Delicado, and Aaron Saide, named its founder by luxurycigarclub.com; on the market since 2017, rolled at Tabacalera Palma, with the Box Pressed (Cubra wrapper from Brazil, Piloto binder, filler of Dominican Criollo 98 and Piloto) and the Delicado (American Connecticut wrapper). In April 2024, an article by the Premium Cigar Association places it among the factory''s high-end brands."}]',
  `gamme_es` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"La marca propia de la fábrica, y la única que firma con su nombre. La palabra designa la propia sala de liado: el lugar donde los torcedores trabajan en filas.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Ligadas dominicanas, capas variadas"},{"name":"Rough Rider","color":"#C9A96E","force":null,"wrapper":"Connecticut, maduro, candela","vitolas":[],"story":"Marca de Jochy Blanco, procedente de la cartera de IndianHead, que compró en 2015 a Bill Bock; la línea Rough Rider Sweets cuenta con tres puros, Connecticut, Maduro y Candela, este último presentado en el PCA 2025 en Robusto (5 x 50), Toro (6 x 52) y Gordo (6 x 60), con tripa de Criollo 98, Piloto Cubano y Camerún, enrollado en Tabacalera Palma. Un artículo de la Premium Cigar Association de abril de 2024 la describe como longfiller, de perilla endulzada."},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Connecticut, habano, maduro","vitolas":[],"story":"Aparecida en 2007 según cigarcentury.com, que la dice hecha por Tabacalera Palma, con capote dominicano y tripa de Nicaragua y de República Dominicana; pasó en 2015 a Jochy Blanco con la compra de IndianHead. En abril de 2024, un artículo de la Premium Cigar Association la sitúa entre las líneas de tripa mixta (mixed-fill) de la fábrica, vendida en cajas."},{"name":"La Instructora","color":"#6B4226","force":"Medium","wrapper":"Cubra brasileño, Connecticut","vitolas":[],"story":"Proyecto conjunto de Jochy Blanco, que realizó la mezcla de la Delicado, y de Aaron Saide, nombrado su fundador por luxurycigarclub.com; en el mercado desde 2017, enrollada en Tabacalera Palma, con la Box Pressed (capa Cubra de Brasil, capote Piloto, tripa de Criollo 98 y de Piloto dominicanos) y la Delicado (capa Connecticut estadounidense). En abril de 2024, un artículo de la Premium Cigar Association la sitúa entre las marcas de gama alta de la fábrica."}]',
  `gamme_de` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"Die eigene Marke der Fabrik und die einzige, die sie mit ihrem Namen zeichnet. Das Wort bezeichnet den Rollsaal selbst — den Raum, in dem die Torcedores in Reihen arbeiten.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Dominikanische Mischungen, wechselnde Deckblätter"},{"name":"Rough Rider","color":"#C9A96E","force":null,"wrapper":"Connecticut, Maduro, Candela","vitolas":[],"story":"Marke von Jochy Blanco, aus dem Portfolio von IndianHead stammend, das er 2015 von Bill Bock erworben hat; die Linie Rough Rider Sweets umfasst drei Zigarren, Connecticut, Maduro und Candela, Letztere auf der PCA 2025 vorgestellt in Robusto (5 x 50), Toro (6 x 52) und Gordo (6 x 60), Einlage aus Criollo 98, Piloto Cubano und Kamerun, gerollt bei Tabacalera Palma. Ein Artikel der Premium Cigar Association vom April 2024 beschreibt sie als longfiller mit gesüßtem Mundstück."},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Connecticut, Habano, Maduro","vitolas":[],"story":"Laut cigarcentury.com 2007 erschienen; die Seite sagt, sie werde von Tabacalera Palma hergestellt, mit dominikanischem Umblatt und Einlage aus Nicaragua und der Dominikanischen Republik; 2015 mit dem Kauf von IndianHead zu Jochy Blanco gekommen. Im April 2024 ordnet ein Artikel der Premium Cigar Association sie unter die Linien mit gemischter Einlage (mixed-fill) der Fabrik ein, in Schachteln verkauft."},{"name":"La Instructora","color":"#6B4226","force":"Medium","wrapper":"Cubra (Brasilien), Connecticut","vitolas":[],"story":"Gemeinschaftsprojekt von Jochy Blanco, der die Mischung der Delicado zusammengestellt hat, und von Aaron Saide, den luxurycigarclub.com als ihren Gründer nennt; seit 2017 auf dem Markt, bei Tabacalera Palma gerollt, mit der Box Pressed (Deckblatt Cubra aus Brasilien, Umblatt Piloto, Einlage aus dominikanischem Criollo 98 und Piloto) und der Delicado (Deckblatt Connecticut aus den USA). Im April 2024 ordnet ein Artikel der Premium Cigar Association sie unter die hochwertigen Marken der Fabrik ein."}]',
  `gamme_zh` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"工厂的自有品牌，也是它唯一以自己名字署名的品牌。这个词本指卷制车间——卷烟师成排工作的那间屋子。","vitolas":["Robusto","Toro","Corona"],"wrapper":"多米尼加配方，茄衣不一"},{"name":"Rough Rider","color":"#C9A96E","force":null,"wrapper":"Connecticut、maduro、candela","vitolas":[],"story":"Jochy Blanco的品牌，源自IndianHead的产品组合，他于2015年自Bill Bock处收购；Rough Rider Sweets产品线共有三款雪茄，即Connecticut、Maduro和Candela，其中Candela在PCA 2025上亮相，规格为Robusto（5 x 50）、Toro（6 x 52）和Gordo（6 x 60），茄芯为Criollo 98、Piloto Cubano和喀麦隆烟叶，在Tabacalera Palma卷制。据Premium Cigar Association 2024年四月的一篇文章，它被描述为longfiller，带甜头。"},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Connecticut、habano、maduro","vitolas":[],"story":"据cigarcentury.com，2007年面世，该网站称其由Tabacalera Palma制造，茄套为多米尼加产，茄芯来自尼加拉瓜和多米尼加共和国；2015年随收购IndianHead而来到Jochy Blanco处。2024年四月，Premium Cigar Association的一篇文章将其列入该工厂的混合茄芯（mixed-fill）产品线，以盒装销售。"},{"name":"La Instructora","color":"#6B4226","force":"Medium","wrapper":"巴西Cubra、Connecticut","vitolas":[],"story":"Jochy Blanco与Aaron Saide的共同项目，前者调配了Delicado，后者被luxurycigarclub.com称为其创始人；2017年起上市，在Tabacalera Palma卷制，包括Box Pressed（巴西Cubra茄衣、Piloto茄套、多米尼加Criollo 98与Piloto茄芯）和Delicado（美国Connecticut茄衣）。2024年四月，Premium Cigar Association的一篇文章将其列入该工厂的高端品牌。"}]',
  `gamme_ar` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"العلامة الخاصة بالمصنع، والوحيدة التي يوقّعها باسمه. والكلمة تسمّي قاعة اللفّ نفسها — الغرفة التي يعمل فيها اللافّون صفوفًا.","vitolas":["Robusto","Toro","Corona"],"wrapper":"مزائج دومينيكية بأغلفة متنوّعة"},{"name":"Rough Rider","color":"#C9A96E","force":null,"wrapper":"Connecticut وmaduro وcandela","vitolas":[],"story":"علامة تعود إلى Jochy Blanco، آتية من محفظة IndianHead التي اشتراها في 2015 من Bill Bock؛ يضم خط Rough Rider Sweets ثلاث سيجارات، Connecticut وMaduro وCandela، وقد قُدّمت الأخيرة في PCA 2025 بمقاسات Robusto (5 x 50) وToro (6 x 52) وGordo (6 x 60)، بحشوة من Criollo 98 وPiloto Cubano والكاميرون، وتُلَفّ في Tabacalera Palma. ويصفها مقال لـ Premium Cigar Association في أبريل 2024 بأنها longfiller ذات رأس محلّى."},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","wrapper":"Connecticut وhabano وmaduro","vitolas":[],"story":"ظهرت في 2007 بحسب cigarcentury.com الذي يقول إنها من صنع Tabacalera Palma، برابط دومينيكي وحشوة من نيكاراغوا وجمهورية الدومينيكان؛ وانتقلت في 2015 إلى Jochy Blanco مع شراء IndianHead. وفي أبريل 2024 يدرجها مقال لـ Premium Cigar Association ضمن خطوط الحشوة المختلطة (mixed-fill) في المصنع، وتُباع في علب."},{"name":"La Instructora","color":"#6B4226","force":"Medium","wrapper":"Cubra برازيلي وConnecticut","vitolas":[],"story":"مشروع مشترك بين Jochy Blanco، الذي أعدّ توليفة Delicado، وAaron Saide، الذي يسميه luxurycigarclub.com مؤسسها؛ في السوق منذ 2017، وتُلَفّ في Tabacalera Palma، وتضم Box Pressed (غلاف خارجي Cubra من البرازيل، ورابط Piloto، وحشوة من Criollo 98 وPiloto دومينيكيين) وDelicado (غلاف خارجي Connecticut أمريكي). وفي أبريل 2024 يدرجها مقال لـ Premium Cigar Association ضمن علامات المصنع الراقية."}]',
  `source` = IF(LOCATE('tabacalerapalma.com (7 octobre 2026 : La Galera, La Instruct', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'tabacalerapalma.com (7 octobre 2026 : La Galera, La Instructora, Rough Rider et Cibao figurent parmi les marques de la page d''accueil ; la fabrique écrit cultiver le tabac et rouler des cigares premium à la main depuis 1936) ; premiumcigars.org « La Galera Cigars: Grounded in the Past, Looking Toward the Future » (15 avril 2024 : Rough Riders, longfiller à bout sucré ; Cuban Aristocrat en boîtes, ligne mixed-fill ; La Instructora, marque haut de gamme ; la fabrique a repris la production des lignes d''IndianHead) ; cigar-coop.com « Cigar News: Tabacalera Palma Acquires IndianHead Cigars and Launches La Galera Brand » (17 novembre 2015 : rachat d''IndianHead à Bill Bock, portefeuille dont Cuban Aristocrat et Rough Ryder Sweets) ; cigar-coop.com « Rough Rider Sweets Candela Launching at PCA 2025 » (25 mars 2025 : Rough Rider appartient à Jochy Blanco ; Sweets Candela, troisième cigare après Connecticut et Maduro, fabrique Tabacalera Palma, formats et tripe) ; cigar-coop.com « PCA 2025: La Galera Cigars / IndianHead Cigars » (31 mai 2025 : IndianHead, maison mère de La Galera, rachetée en 2015 par Jochy Blanco) ; cigarcentury.com « Cuban Aristocrat » (7 octobre 2026 : parue en 2007, faite par Tabacalera Palma, capes Connecticut équatorien, habano et maduro, liant dominicain, tripe du Nicaragua et de République dominicaine, Mild à Medium) ; luxurycigarclub.com « La Instructora Delicado » (7 octobre 2026 : Aaron Saide fondateur, Jochy Blanco assembleur, roulée à Tabacalera La Palma, cape Connecticut américain, liant et tripe dominicains, force Medium, sur le marché depuis 2017) ; cigarslover.com « La Instructora Box Pressed #2 » (28 mars 2018 : cape Cubra brésilien, liant Piloto, tripe Criollo 98 et Piloto, fabrique Tabacalera Palma)')),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacalera Palma';

-- ── Tabacalera del Oriente — paragraphe : Inca ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Inca n''est pas une marque de la fabrique : elle est à Mitche', `history`) > 0, `history`, CONCAT(`history`, '

', 'Inca n''est pas une marque de la fabrique : elle est à Mitchell Orchant, directeur du détaillant britannique C.Gars Ltd, qui l''a lancée en 2012 au Royaume-Uni sous le nom d''Inka Secret Blend. Ce sont des puros péruviens roulés à Tarapoto par Tabacalera del Oriente. La version américaine s''écrit Inca ; en 2015, Alec Bradley en assurait la distribution. En octobre 2026, la boutique allemande Tabak Träber vend l''Inca Tambo, distribué par Kopp Tobaccos, et des boutiques britanniques proposent l''Inka Secret Blend.')),
  `history_en` = IF(LOCATE('Inca is not a brand of the factory: it belongs to Mitchell O', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Inca is not a brand of the factory: it belongs to Mitchell Orchant, director of the British retailer C.Gars Ltd, who launched it in 2012 in the United Kingdom under the name Inka Secret Blend. They are Peruvian puros rolled in Tarapoto by Tabacalera del Oriente. The American version is spelled Inca; in 2015, Alec Bradley handled its distribution. In October 2026, the German shop Tabak Träber sells the Inca Tambo, distributed by Kopp Tobaccos, and British shops offer the Inka Secret Blend.')),
  `history_es` = IF(LOCATE('Inca no es una marca de la fábrica: pertenece a Mitchell Orc', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Inca no es una marca de la fábrica: pertenece a Mitchell Orchant, director del minorista británico C.Gars Ltd, que la lanzó en 2012 en el Reino Unido con el nombre de Inka Secret Blend. Son puros peruanos enrollados en Tarapoto por Tabacalera del Oriente. La versión estadounidense se escribe Inca; en 2015, Alec Bradley se encargaba de su distribución. En octubre de 2026, la tienda alemana Tabak Träber vende el Inca Tambo, distribuido por Kopp Tobaccos, y tiendas británicas ofrecen el Inka Secret Blend.')),
  `history_de` = IF(LOCATE('Inca ist keine Marke der Fabrik: Sie gehört Mitchell Orchant', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Inca ist keine Marke der Fabrik: Sie gehört Mitchell Orchant, dem Direktor des britischen Einzelhändlers C.Gars Ltd, der sie 2012 im Vereinigten Königreich unter dem Namen Inka Secret Blend auf den Markt gebracht hat. Es sind peruanische puros, die in Tarapoto von Tabacalera del Oriente gerollt werden. Die amerikanische Version schreibt sich Inca; 2015 sorgte Alec Bradley für den Vertrieb. Im Oktober 2026 verkauft das deutsche Geschäft Tabak Träber den Inca Tambo, vertrieben von Kopp Tobaccos, und britische Geschäfte bieten den Inka Secret Blend an.')),
  `history_zh` = IF(LOCATE('Inca并非该工厂的品牌：它归Mitchell Orchant所有，他是英国零售商C.Gars Ltd的董事，于2012', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'Inca并非该工厂的品牌：它归Mitchell Orchant所有，他是英国零售商C.Gars Ltd的董事，于2012年在英国以Inka Secret Blend之名推出。这些是由Tabacalera del Oriente在Tarapoto卷制的秘鲁puros。美国版写作Inca；2015年，Alec Bradley负责其分销。2026年十月，德国商店Tabak Träber销售Inca Tambo，由Kopp Tobaccos分销，英国商店则销售Inka Secret Blend。')),
  `history_ar` = IF(LOCATE('Inca ليست علامة للمصنع: فهي ملك Mitchell Orchant، مدير تاجر ', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'Inca ليست علامة للمصنع: فهي ملك Mitchell Orchant، مدير تاجر التجزئة البريطاني C.Gars Ltd، الذي أطلقها في 2012 في المملكة المتحدة باسم Inka Secret Blend. وهي puros من بيرو تُلَفّ في Tarapoto لدى Tabacalera del Oriente. وتُكتب النسخة الأمريكية Inca؛ وفي 2015 كانت Alec Bradley تتولى توزيعها. وفي أكتوبر 2026 يبيع المتجر الألماني Tabak Träber النسخة Inca Tambo، التي توزعها Kopp Tobaccos، وتعرض متاجر بريطانية Inka Secret Blend.')),
  `mentions` = '["Inca"]',
  `source` = IF(LOCATE('cigar-coop.com « Cigar Review: Inca Secret Blend Tambo » (17', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « Cigar Review: Inca Secret Blend Tambo » (17 mai 2015 : projet mené par Mitchell Orchant, directeur de C.Gars Ltd, détaillant britannique ; fabricant Tabacalera del Oriente, Tarapoto, que dirige Gennaro Lettieri ; puro entièrement péruvien ; version américaine nommée Inca, version britannique de 2012 nommée Inka ; Alec Bradley distributeur américain) ; incacigars.com « Reviews » (non daté : Mitchell Orchant, directeur de C.Gars Ltd, derrière la marque Inca Secret Blend ; fabrique Tabacalera del Oriente à Tarapoto, propriété de Gennaro Lettieri) ; tabak-traeber.de « Inca Tambo - Cigars » (7 octobre 2026 : en vente, expédition en 3-4 jours ; distribué par Kopp Tobaccos GmbH & Co. KG ; marque créditée à Mitchell Orchant ; fait à Tabacalera del Oriente, Tarapoto) ; turmeaus.co.uk « Inka Secret Blend Cigars » (7 octobre 2026 : gamme Inka Secret Blend en vente au Royaume-Uni, orthographes Inka et Inca) ; simplycigars.co.uk « Inka Secret Blend Cigars » (7 octobre 2026 : cigares péruviens, roulés à la main, en vente au Royaume-Uni)')),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacalera del Oriente';

-- ── Les sceaux des champs touchés, calculés depuis les colonnes ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'Foundation Cigar Company' hote, 'history' champ
        UNION ALL SELECT 'Foundation Cigar Company' hote, 'gamme' champ
        UNION ALL SELECT 'Freud Cigar Co.' hote, 'gamme' champ
        UNION ALL SELECT 'General Cigar' hote, 'history' champ
        UNION ALL SELECT 'General Cigar' hote, 'gamme' champ
        UNION ALL SELECT 'Gran Habano' hote, 'history' champ
        UNION ALL SELECT 'Gran Habano' hote, 'gamme' champ
        UNION ALL SELECT 'J.C. Newman' hote, 'gamme' champ
        UNION ALL SELECT 'Joya de Nicaragua' hote, 'history' champ
        UNION ALL SELECT 'Kelner Boutique Factory' hote, 'history' champ
        UNION ALL SELECT 'Kristoff' hote, 'history' champ
        UNION ALL SELECT 'La Aroma de Cuba' hote, 'history' champ
        UNION ALL SELECT 'La Aurora' hote, 'history' champ
        UNION ALL SELECT 'Miami Cigar & Co.' hote, 'gamme' champ
        UNION ALL SELECT 'My Father' hote, 'history' champ
        UNION ALL SELECT 'My Father' hote, 'gamme' champ
        UNION ALL SELECT 'Oliva' hote, 'history' champ
        UNION ALL SELECT 'Oscar Valladares' hote, 'gamme' champ
        UNION ALL SELECT 'Ozgener Family Cigars' hote, 'history' champ
        UNION ALL SELECT 'Plasencia' hote, 'history' champ
        UNION ALL SELECT 'Rocky Patel' hote, 'gamme' champ
        UNION ALL SELECT 'Tabacalera Palma' hote, 'gamme' champ
        UNION ALL SELECT 'Tabacalera del Oriente' hote, 'history' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `maj` = NOW();

