UNION ALL SELECT 'Foundation Cigar Company', 'en', 'paragraphe', LOCATE('In March 2024, Foundation announced that the name El Güegüen', `history_en`) > 0 FROM `brands` WHERE `name` = 'Foundation Cigar Company'
UNION ALL SELECT 'Foundation Cigar Company', 'es', 'paragraphe', LOCATE('En marzo de 2024, Foundation anunció que el nombre El Güegüe', `history_es`) > 0 FROM `brands` WHERE `name` = 'Foundation Cigar Company'
UNION ALL SELECT 'Foundation Cigar Company', 'de', 'paragraphe', LOCATE('Im März 2024 gab Foundation bekannt, dass der Name El Güegüe', `history_de`) > 0 FROM `brands` WHERE `name` = 'Foundation Cigar Company'
